/**
 * Handles the interception logic for the API Proxy.
 */
export function interceptApiCall(moduleName: string, methodName: string, _originalArgs: any[]) {
  const registryKey = `${moduleName}.${methodName}`;
  const state = useStore.getState();

  const _isExplorer = state.isExplorerMode;
  const _dismissedIds = state.dismissedSampleIds;

  // If we are currently bridging demo data to reality, DO NOT intercept.
  if (state.isBridging) {
    return null;
  }

  // GHOST SEEDING: Proactive injection for Classrooms
  if (registryKey === 'classrooms.getByTeacher' || registryKey === 'classrooms.getByStudent') {
    // We let the original call proceed to check for real data
    return null;
  }

  // Traditional isDemoMode (Global Sandbox Toggle)
  if (isDemo()) {
    const mockGetter = MOCK_DATA_REGISTRY[registryKey];
    if (
      mockGetter &&
      (methodName.startsWith('get') || methodName.startsWith('list') || methodName === 'getAll')
    ) {
      return Promise.resolve(mockGetter());
    }

    if (
      methodName.startsWith('create') ||
      methodName.startsWith('update') ||
      methodName.startsWith('delete') ||
      methodName.startsWith('add')
    ) {
      // Block write operations in demo mode
      console.log(`[DEMO MODE] Blocked write operation: ${registryKey}.${methodName}`);
      // Return a successful mock response without executing real DB writes
      return Promise.resolve({
        success: true,
        message: 'Demo mode: Operation simulated successfully',
        data: null,
      });
    }
  }

  return null;
}

/**
 * Enhanced Proxy specifically for "Ghost" merging.
 * This can be called after a real API result to inject samples if needed.
 */
export function processGhostData(moduleName: string, methodName: string, realData: any) {
  const state = useStore.getState();
  const isExplorer = state.isExplorerMode;
  const dismissedIds = state.dismissedSampleIds;

  if (!isExplorer) return realData;

  // 1. GHOST CLASSROOMS
  if (
    moduleName === 'classrooms' &&
    methodName.startsWith('get') &&
    Array.isArray(realData) &&
    realData.length === 0
  ) {
    const registryKey = `${moduleName}.${methodName}`;
    const mockGetter = MOCK_DATA_REGISTRY[registryKey];

    if (mockGetter) {
      const rawMocks = mockGetter();
      return rawMocks
        .filter((m: any) => !dismissedIds.includes(m.id))
        .map((m: any) => ({ ...m, is_sample: true }));
    }
  }

  // 2. GHOST SCHOOL STATS
  if (moduleName === 'school' && methodName === 'getSchoolStats') {
    const stats = realData;
    const isEmpty =
      stats.total_students === 0 && stats.total_teachers === 0 && stats.total_classrooms === 0;

    if (isEmpty) {
      const mockGetter = MOCK_DATA_REGISTRY['school.getSchoolStats'];
      if (mockGetter) {
        const mockStats = mockGetter();
        return { ...mockStats, is_sample: true };
      }
    }
  }

  // 3. GHOST SECTIONS
  if (
    moduleName === 'school' &&
    methodName === 'getSections' &&
    Array.isArray(realData) &&
    realData.length === 0
  ) {
    // We might want to inject mock sections here if we had some in registry
    // For now, classrooms is the primary focus, but let's be ready
    const registryKey = `${moduleName}.${methodName}`;
    const mockGetter = MOCK_DATA_REGISTRY[registryKey];
    if (mockGetter) {
      return mockGetter().map((m: any) => ({ ...m, is_sample: true }));
    }
  }

  return realData;
}

import { APIError } from '../types/API';
import { identityAPI } from './identity';
import { supabase } from './supabase';

export interface StudentEcho {
  id: string;
  classroom_id: string;
  school_id: string;
  student_id: string;
  content: string;
  is_anonymous: boolean;
  is_read: boolean;
  teacher_response?: string;
  responded_by?: string;
  responded_at?: string;
  created_at: string;
  updated_at: string;
}

export const echoAPI = {
  /**
   * Send an echo (feedback) from a student to their class teacher.
   */
  async sendEcho(echo: {
    classroom_id: string;
    school_id?: string;
    content: string;
    is_anonymous: boolean;
  }): Promise<StudentEcho> {
    const myId = await identityAPI.getMyInternalId();
    if (!myId) throw new APIError('Not authenticated', 'AUTH_REQUIRED');

    const { data, error } = await supabase
      .from('classroom_echo_feedback')
      .insert([
        {
          ...echo,
          student_id: myId,
          is_read: false,
        },
      ])
      .select('*')
      .single();

    if (error) throw new APIError('Failed to send echo', error.code, error);
    return data as StudentEcho;
  },

  /**
   * Fetch echoes for a student (their own feedback history).
   */
  async getMyEchoes(): Promise<StudentEcho[]> {
    const myId = await identityAPI.getMyInternalId();
    if (!myId) throw new APIError('Not authenticated', 'AUTH_REQUIRED');

    const { data, error } = await supabase
      .from('classroom_echo_feedback')
      .select('*')
      .eq('student_id', myId)
      .order('created_at', { ascending: false });

    if (error) throw new APIError('Failed to fetch your echoes', error.code, error);
    return (data || []) as StudentEcho[];
  },

  /**
   * Fetch echoes for a classroom (Unified for student and teacher context).
   */
  async getEchoesByClassroom(classroomId: string): Promise<any[]> {
    const myId = await identityAPI.getMyInternalId();
    if (!myId) throw new APIError('Not authenticated', 'AUTH_REQUIRED');

    // Check if teacher for this classroom (simplified check for now)
    const { data: classData } = await supabase
      .from('classrooms')
      .select('teacher_id')
      .eq('id', classroomId)
      .single();

    const isTeacher = classData?.teacher_id === myId;

    let query = supabase
      .from('classroom_echo_feedback')
      .select(`
                *,
                student:users!classroom_echo_feedback_student_id_fkey(full_name, avatar_url)
            `)
      .eq('classroom_id', classroomId);

    if (!isTeacher) {
      // Students only see their own echoes
      query = query.eq('student_id', myId);
    }

    const { data, error } = await query
      .order('is_read', { ascending: true })
      .order('created_at', { ascending: false });

    if (error) throw new APIError('Failed to fetch classroom echoes', error.code, error);

    return (data || []).map((echo: any) => ({
      ...echo,
      student_name: echo.is_anonymous ? 'Anonymous Soul' : echo.student?.full_name,
      student_avatar: echo.is_anonymous ? null : echo.student?.avatar_url,
    }));
  },

  /**
   * Fetch echoes for a teacher (feedback from their students).
   */
  async getTeacherEchoes(classroomId: string): Promise<StudentEcho[]> {
    const { data, error } = await supabase
      .from('classroom_echo_feedback')
      .select(`
                *,
                student:users!classroom_echo_feedback_student_id_fkey(full_name, avatar_url)
            `)
      .eq('classroom_id', classroomId)
      .order('is_read', { ascending: true })
      .order('created_at', { ascending: false });

    if (error) throw new APIError('Failed to fetch student echoes', error.code, error);

    // Handle anonymity in the API layer for safety
    return (data || []).map((echo: any) => ({
      ...echo,
      student_name: echo.is_anonymous ? 'Anonymous Soul' : echo.student?.full_name,
      student_avatar: echo.is_anonymous ? null : echo.student?.avatar_url,
    })) as (StudentEcho & { student_name: string; student_avatar?: string })[];
  },

  /**
   * Respond to an echo (Teacher action).
   */
  async respondToEcho(echoId: string, response: string): Promise<StudentEcho> {
    const myId = await identityAPI.getMyInternalId();
    if (!myId) throw new APIError('Not authenticated', 'AUTH_REQUIRED');

    const { data, error } = await supabase
      .from('classroom_echo_feedback')
      .update({
        teacher_response: response,
        responded_by: myId,
        responded_at: new Date().toISOString(),
        is_read: true,
      })
      .eq('id', echoId)
      .select('*')
      .single();

    if (error) throw new APIError('Failed to respond to echo', error.code, error);
    return data as StudentEcho;
  },

  /**
   * Mark an echo as read without responding.
   */
  async markAsRead(echoId: string): Promise<void> {
    const { error } = await supabase
      .from('classroom_echo_feedback')
      .update({ is_read: true })
      .eq('id', echoId);

    if (error) throw new APIError('Failed to mark echo as read', error.code, error);
  },
};

