    await logGradingAudit({
      action: 'grading_published_completion_read',
      entityId: schoolId,
      executorId: audit?.actorId,
      metadata: {
        schoolId,
        viewDate,
        reason: audit?.reason ?? null,
        accessKind: audit?.accessKind ?? 'institutional_read',
