import { socialAPI } from '../social';
import { supabase } from '../supabase';

export const notificationKeys = {
  all: ['notifications'] as const,
  list: (userId: string | undefined) => [...notificationKeys.all, userId, 'list'] as const,
  count: (userId: string | undefined) => [...notificationKeys.all, userId, 'unread-count'] as const,
};

/**
 * Hook for managing real-time notifications, promoted to @repo/core.
 */
export function useNotificationHooks() {
  const queryClient = useQueryClient();
  const userId = useStore((state) => state.user?.id);

  // Fetch list
  const listQuery = useQuery({
    queryKey: notificationKeys.list(userId),
    queryFn: () => socialAPI.getNotifications(40),
    enabled: !!userId,
    staleTime: 60_000,
  });

  // Unread badge count
  const countQuery = useQuery({
    queryKey: notificationKeys.count(userId),
    queryFn: socialAPI.getUnreadNotificationCount,
    enabled: !!userId,
    staleTime: 30_000,
    refetchInterval: 60_000,
  });

  // Real-time subscription
  React.useEffect(() => {
    if (!userId) return;

    const channel = supabase
      .channel(`notifications-${userId}`)
      .on(
        'postgres_changes' as any,
        {
          event: 'INSERT',
          schema: 'public',
          table: 'notifications',
          filter: `user_id=eq.${userId}`,
        },
        (payload: any) => {
          queryClient.setQueryData<Notification[]>(notificationKeys.list(userId), (prev) => [
            payload.new as Notification,
            ...(prev ?? []),
          ]);
          queryClient.setQueryData<number>(
            notificationKeys.count(userId),
            (prev) => (prev ?? 0) + 1,
          );
        },
      )
      .on(
        'postgres_changes' as any,
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'notifications',
          filter: `user_id=eq.${userId}`,
        },
        () => {
          queryClient.invalidateQueries({
            queryKey: notificationKeys.list(userId),
          });
          queryClient.invalidateQueries({
            queryKey: notificationKeys.count(userId),
          });
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [userId, queryClient]);

  const markReadMutation = useMutation({
    mutationFn: (notifId: string) => socialAPI.markNotificationRead(notifId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: notificationKeys.all });
    },
  });

  const markAllReadMutation = useMutation({
    mutationFn: socialAPI.markAllNotificationsRead,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: notificationKeys.all });
    },
  });

  return {
    notifications: listQuery.data ?? [],
    isLoading: listQuery.isLoading,
    unreadCount: countQuery.data ?? 0,
    markRead: markReadMutation.mutateAsync,
    markAllRead: markAllReadMutation.mutateAsync,
    isMarkingRead: markReadMutation.isPending || markAllReadMutation.isPending,
  };
}

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useStore } from '../../store/useStore';
import { communityAPI } from '../community';
import { supabase } from '../supabase';

export const pollKeys = {
  all: ['community', 'polls'] as const,
  detail: (postId: string) => [...pollKeys.all, postId] as const,
};

/**
 * Modern logic for Community Polls using TanStack Query v5.
 * Promoted to @repo/core/api/hooks/poll.hooks.ts.
 */
export function usePollHooks(postId: string) {
  const queryClient = useQueryClient();
  const { user } = useStore();

  const query = useQuery({
    queryKey: pollKeys.detail(postId),
    queryFn: async () => {
      // Fetch vote counts
      const { data: countData, error: countError } = await supabase
        .from('community_poll_votes')
        .select('option_id')
        .eq('post_id', postId);

      if (countError) throw countError;

      const counts: Record<string, number> = {};
      let total = 0;
      (countData ?? []).forEach((v) => {
        counts[v.option_id] = (counts[v.option_id] ?? 0) + 1;
        total++;
      });

      // Fetch current user votes if logged in
      let userVotes: string[] = [];
      if (user?.id) {
        const { data: myVotesData, error: myVotesError } = await supabase
          .from('community_poll_votes')
          .select('option_id')
          .eq('post_id', postId)
          .eq('user_id', user.id);

        if (myVotesError) throw myVotesError;
        userVotes = (myVotesData ?? []).map((v) => v.option_id);
      }

      return {
        counts,
        totalVotes: total,
        userVotes: new Set(userVotes),
      };
    },
    enabled: !!postId,
  });

  const voteMutation = useMutation({
    mutationFn: ({ optionId, allowMultiple }: { optionId: string; allowMultiple: boolean }) =>
      communityAPI.voteInPoll(postId, optionId, allowMultiple),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: pollKeys.detail(postId) });
    },
  });

  return {
    ...query.data,
    isLoading: query.isLoading,
    isVoting: voteMutation.isPending,
    handleVote: (optionId: string, allowMultiple = false) =>
      voteMutation.mutate({ optionId, allowMultiple }),
    refreshVotes: () => queryClient.invalidateQueries({ queryKey: pollKeys.detail(postId) }),
  };
}

