export const moonPhaseAPI = {
  /**
   * Get the current moon phase.
   * Pure computation \u2014 no database access, instant.
   */
  getCurrentMoonPhase(now = new Date()): MoonPhase {
    const age = getLunarAge(now);
    const name = ageToPhase(age);
    const illumination = ageToIllumination(age);
    const isPoya = name === 'full_moon' || (age > 13.5 && age < 15.5);

    return {
      name,
      illumination: Math.round(illumination * 100) / 100,
      age: Math.round(age * 10) / 10,
      emoji: MOON_EMOJIS[name],
      invitation_en: MOON_PHASE_INVITATIONS[name],
      is_poya: isPoya,
    };
  },

  /**
   * Get the full school season context for a given date.
   * Used by the home screen to determine the ambient aesthetic and invitation.
   */
  getSchoolSeasonContext(now = new Date()): SchoolSeasonContext {
    const moon = this.getCurrentMoonPhase(now);
    const month = now.getMonth() + 1;
    const season = getSriLankanSeason(month);

    // Check for upcoming calendar event (within 3 days)
    let upcoming_event: SriLankanCalendarEvent | null = null;

    // Vesak Poya (May full moon) \u2014 special treatment
    if (month === 5 && moon.is_poya) {
      upcoming_event = {
        name_en: 'Vesak Poya',
        name_si: '\u0DC0\u0DD9\u0DC3\u0D9A\u0DCA \u0DB4\u0DDD\u0DBA',
        date: now.toISOString().slice(0, 10),
        type: 'poya',
        app_theme: 'vesak',
      };
    }
    // Sinhala/Tamil New Year
    else if (month === 4 && (now.getDate() === 13 || now.getDate() === 14)) {
      upcoming_event = {
        name_en: 'Sinhala and Tamil New Year',
        name_si:
          '\u0DC3\u0DD2\u0D82\u0DC4\u0DBD \u0DC4\u0DCF \u0DAF\u0DD9\u0DB8\u0DC5 \u0D85\u0DBD\u0DD4\u0DAD\u0DCA \u0D85\u0DC0\u0DD4\u0DBB\u0DD4\u0DAF\u0DCA\u0DAF',
        date: `${now.getUTCFullYear()}-04-14`,
        type: 'new_year',
        app_theme: 'new_year',
      };
    }
    // Other Poya days
    else if (moon.is_poya && POYA_NAMES[month]) {
      const poya = POYA_NAMES[month];
      upcoming_event = {
        name_en: poya.name_en,
        name_si: poya.name_si,
        date: now.toISOString().slice(0, 10),
        type: 'poya',
        app_theme: 'poya',
      };
    }

    // Combine moon + season invitation
    const seasonal_invitation_en = upcoming_event
      ? `${upcoming_event.name_en} \u2014 ${moon.invitation_en.toLowerCase()}`
      : `${SEASONAL_INVITATIONS[season]} ${moon.invitation_en}`;

    return {
      moon,
      season,
      upcoming_event,
      seasonal_invitation_en,
    };
  },

  /**
   * Generate a moon calendar for a given month (year + month, 1-indexed).
   * Returns the phase for each day of the month.
   * Used by the principal's Moon Calendar feature.
   */
  getMonthCalendar(
    year: number,
    month: number,
  ): Array<{
    date: string;
    phase: MoonPhaseName;
    emoji: string;
    is_poya: boolean;
  }> {
    const daysInMonth = new Date(year, month, 0).getDate();
    const calendar = [];

    for (let day = 1; day <= daysInMonth; day++) {
      const date = new Date(Date.UTC(year, month - 1, day, 12, 0, 0));
      const age = getLunarAge(date);
      const name = ageToPhase(age);
      calendar.push({
        date: `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`,
        phase: name,
        emoji: MOON_EMOJIS[name],
        is_poya: age > 13.5 && age < 15.5,
      });
    }

    return calendar;
  },

  /**
   * Get the Poya days for a given year.
   * Used for the school planning calendar view.
   */
  getPoyaDays(year: number): Array<{ date: string; name_en: string; name_si: string }> {
    const poyaDays = [];

    for (let month = 1; month <= 12; month++) {
      // Find the full moon date for this month by iterating days
      const calendar = this.getMonthCalendar(year, month);
      const fullMoonDay = calendar.find((d) => d.is_poya);
      const poyaName = POYA_NAMES[month];
      if (fullMoonDay && poyaName) {
        poyaDays.push({
          date: fullMoonDay.date,
          name_en: poyaName.name_en,
          name_si: poyaName.name_si,
        });
      }
    }

    return poyaDays;
  },
};

import { composeUserAbilities } from '../logic/permissions/composer';
import type { Role } from '../logic/schemas/role.schema';
import type { ClassroomJoinRequest, RequestStatus, SchoolJoinRequest } from '../types/Onboarding';
import { supabase } from './supabase';

/**
 * Onboarding API (Triple Helix BDD Implementation)
 * Handles "No Trust" verification flows for schools and classrooms.
 */
export const onboardingAPI = {
  /**
   * SCHOOL JOIN FLOW
   */

  async requestSchoolJoin(
    userId: string,
    schoolId: string,
    role: Role,
  ): Promise<SchoolJoinRequest> {
    const { data, error } = await supabase
      .from('school_join_requests')
      .insert([{ user_id: userId, school_id: schoolId, role, status: 'pending' }])
      .select()
      .single();

    if (error) throw error;

    // Notify principal logic would go here (Trigger or follow-up)
    return data;
  },

  async handleSchoolRequest(
    requestId: string,
    status: RequestStatus,
    _adminId: string,
  ): Promise<void> {
    const { error } = await supabase
      .from('school_join_requests')
      .update({ status, updated_at: new Date().toISOString() })
      .eq('id', requestId);

    if (error) throw error;

    if (status === 'approved') {
      // Get user_id from request
      const { data: request } = await supabase
        .from('school_join_requests')
        .select('user_id, school_id')
        .eq('id', requestId)
        .single();

      if (request) {
        // Update user school_id
        await supabase
          .from('users')
          .update({ school_id: request.school_id })
          .eq('id', request.user_id);

        // Add notification
        await this.createNotification(
          request.user_id,
          'join_request_approved',
          'School Joined',
          'Your request to join the school has been approved.',
        );
      }
    }
  },

  /**
   * CLASSROOM JOIN FLOW
   */

  async requestClassroomJoin(
    userId: string,
    classroomId: string,
    role: string,
    subjectLabel?: string,
  ): Promise<ClassroomJoinRequest> {
    // 1. Create classroom join request
    const { data: request, error } = await supabase
      .from('classroom_join_requests')
      .insert([
        {
          user_id: userId,
          classroom_id: classroomId,
          role,
          subject_label: subjectLabel,
          status: 'pending',
        },
      ])
      .select()
      .single();

    if (error) throw error;

    // 2. Find linked community group and create pending membership
    const { data: group } = await supabase
      .from('community_groups')
      .select('id')
      .eq('classroom_id', classroomId)
      .single();

    if (group) {
      const ability = composeUserAbilities({ roles: [role as Role] });
      // POA: Use capability to determine group capacity instead of hardcoded roles
      const capacity = ability.can('manage', 'CommunityGroup') ? 'admin' : 'member';

      await supabase.from('group_members').insert([
        {
          group_id: group.id,
          user_id: userId,
          capacity,
          status: 'pending',
        },
      ]);
    }

    return request;
  },

  async handleClassroomRequest(
    requestId: string,
    status: RequestStatus,
    _classTeacherId: string,
  ): Promise<void> {
    // 1. Update classroom request status
    const { error } = await supabase
      .from('classroom_join_requests')
      .update({ status, updated_at: new Date().toISOString() })
      .eq('id', requestId);

    if (error) throw error;

    // 2. Sync with community group membership
    const { data: request } = await supabase
      .from('classroom_join_requests')
      .select('user_id, classroom_id, role')
      .eq('id', requestId)
      .single();

    if (request && status === 'approved') {
      // Find linked group
      const { data: group } = await supabase
        .from('community_groups')
        .select('id')
        .eq('classroom_id', request.classroom_id)
        .single();

      if (group) {
        // Activate group membership
        await supabase
          .from('group_members')
          .update({ status: 'active' })
          .eq('group_id', group.id)
          .eq('user_id', request.user_id);
      }

      const ability = composeUserAbilities({ roles: [request.role as Role] });

      if (ability.can('manage', 'StudentDashboard')) {
        await supabase
          .from('classroom_students')
          .insert([{ student_id: request.user_id, classroom_id: request.classroom_id }]);
      } else if (ability.can('manage', 'TeacherDashboard')) {
        // If it's a teacher request being approved (e.g. by admin and they join as co-teacher)
        await supabase
          .from('classrooms')
          .update({ teacher_id: request.user_id })
          .eq('id', request.classroom_id)
          .is('teacher_id', null);
      }

      await this.createNotification(
        request.user_id,
        'join_request_approved',
        'Classroom Joined',
        'You have been admitted to the classroom sanctuary.',
      );
    } else if (request && status === 'rejected') {
      // Find linked group
      const { data: group } = await supabase
        .from('community_groups')
        .select('id')
        .eq('classroom_id', request.classroom_id)
        .single();

      if (group) {
        // Reject group membership
        await supabase
          .from('group_members')
          .update({ status: 'rejected' })
          .eq('group_id', group.id)
          .eq('user_id', request.user_id);
      }
    }
  },

  /**
   * NOTIFICATIONS
   */

  async createNotification(
    userId: string,
    type: string,
    title: string,
    message: string,
    metadata: any = {},
  ): Promise<void> {
    await supabase
      .from('notifications')
      .insert([{ user_id: userId, type, title, message, metadata }]);
  },

  async getNotifications(userId: string) {
    const { data, error } = await supabase
      .from('notifications')
      .select('*')
      .eq('user_id', userId)
      .order('created_at', { ascending: false });

    if (error) throw error;
    return data;
  },

  async updateNotificationStatus(notificationId: string, isRead: boolean): Promise<void> {
    await supabase.from('notifications').update({ is_read: isRead }).eq('id', notificationId);
  },

  /**
   * DANGEROUS ACTIONS: USER REMOVAL
   */

  async removeUserFromSpace(
    userId: string,
    targetId: string,
    type: 'school' | 'classroom',
  ): Promise<void> {
    if (type === 'school') {
      // 1. Remove from school_id in users table
      await supabase.from('users').update({ school_id: null }).eq('id', userId);

      // 2. Cascade removal from all school-specific community groups
      // (Assuming a trigger or complex query handles this, or implement here)
    } else {
      // 1. Remove from classroom_students
      await supabase
        .from('classroom_students')
        .delete()
        .eq('student_id', userId)
        .eq('classroom_id', targetId);

      // 2. Remove from classroom-specific community group
      const { data: group } = await supabase
        .from('community_groups')
        .select('id')
        .eq('classroom_id', targetId)
        .single();

      if (group) {
        await supabase
          .from('group_members')
          .delete()
          .eq('group_id', group.id)
          .eq('user_id', userId);
      }
    }

    // 3. Notify the user
    await this.createNotification(
      userId,
      'space_removal',
      'Access Revoked',
      `You have been removed from the ${type}.`,
    );
  },

  /**
   * PROFILE
   */

  async completeProfile(
    userId: string,
    fullName: string,
    roleLabel: string,
    bio?: string,
    indexNumber?: string,
    nicNumber?: string,
  ): Promise<void> {
    const { error } = await supabase
      .from('users')
      .update({
        full_name: fullName,
        authority_label: roleLabel,
        bio,
        index_number: indexNumber,
        nic_number: nicNumber,
        profile_completed: true,
      })
      .eq('id', userId);

    if (error) throw error;
  },
};

import { AuthorityInterceptor } from '../logic/permissions/AuthorityInterceptor';
import { composeUserAbilities } from '../logic/permissions/composer';
import type { Role } from '../logic/schemas/role.schema';
import { type TenantKind, UserContextSchema } from '../logic/schemas/user.schema';
import { useStore } from '../store/useStore';

/**
 * createPOAProxy
 *
 * The Single Source of Truth for Authority Enforcement.
 * This proxy wraps API modules and automatically validates the 'metadata.authority'
 * defined in ts-rest contracts against the user's current CASL ability.
 */
export function createPOAProxy<T extends object>(
  moduleName: string,
  target: T,
  contract?: Record<string, any>,
  methodMapping: Record<string, string> = {},
  options: { strictUnmappedMethods?: boolean } = {},
): T {
  return new Proxy(target, {
    get(obj: T, prop: string | symbol) {
      const originalMethod = (obj as Record<string | symbol, unknown>)[prop];

      if (typeof originalMethod === 'function' && typeof prop === 'string') {
        return async (...args: unknown[]) => {
          // 1. Resolve User Context from Store
          const state = useStore.getState();
          const user = state.user;
          const schoolType = state.schoolType;

          const roles = (user?.roles || []) as Role[];
          const hasGlobalAccess = roles.some((r) => ['founder', 'developer', 'admin'].includes(r));

          const context = UserContextSchema.parse({
            userId: user?.id || null,
            email: user?.email || null,
            schoolId: user?.school_id || null,
            tenancyName: user?.organization_name || null,
            tenancy: {
              kind: (user?.tenant_kind || 'customer') as TenantKind,
              isPersonal: schoolType === 'personal_workspace',
            },
            tenantKind: (user?.tenant_kind || 'customer') as TenantKind,
            roles,
            authority: (user?.authority as Role) || roles[0] || null,
            isAnonymous: !user || !!user?.is_anonymous,
            hasGlobalAccess,
            isPersonal: schoolType === 'personal_workspace',
          });

          // 2. Compose Ability
          const ability = composeUserAbilities(context);

          // 3. Resolve Authority Metadata from Contract
          // Try mapping, then exact match, or fallback to the method name itself in the contract router
          const contractKey = methodMapping[prop] || prop;
          const contractEntry = contract?.[contractKey] as Record<string, unknown> | undefined;
          const metadata = contractEntry?.['metadata'];

          if (metadata && typeof metadata === 'object' && 'authority' in metadata) {
            if (__DEV__) {
              console.log(`[POA Interceptor] Verifying authority for ${moduleName}.${prop}...`);
            }
            await AuthorityInterceptor.enforce(ability, metadata);
          } else {
            if (options.strictUnmappedMethods) {
              throw new Error(
                `POA contract coverage missing for ${moduleName}.${prop} (expected contract route "${contractKey}")`,
              );
            }
          }

          // 4. Execute original method
          return originalMethod.apply(obj, args);
        };
      }

      return originalMethod;
    },
  });
}

import { supabase } from './supabase';

export interface PresenceFallbackCountOptions {
  targetRoles: string[];
  isCumulative: boolean;
  userId?: string;
  windowMs?: number;
}

export interface PresenceSessionOptions {
  userId: string;
  userRole: string;
  userVibe?: string;
  channelName: string;
  onCountChange: (count: number) => void;
  onOfflineChange: (offline: boolean) => void;
}

export async function fetchPresenceFallbackCount(
  options: PresenceFallbackCountOptions,
): Promise<number> {
  const fiveMinutesAgo = new Date(Date.now() - (options.windowMs ?? 5 * 60 * 1000)).toISOString();
  let query = supabase
    .from('users')
    .select('id', { count: 'exact', head: true })
    .gte('last_seen_at', fiveMinutesAgo);

  if (!options.isCumulative) {
    query = query.in('role', options.targetRoles);
  } else if (options.userId && options.userId !== 'guest') {
    query = query.neq('id', options.userId);
  }

  const { count, error } = await query;

  if (error) throw error;
  return count ?? 0;
}

export async function markUserPresenceSeen(userId: string): Promise<void> {
  const { error } = await supabase
    .from('users')
    .update({ last_seen_at: new Date().toISOString() })
    .eq('id', userId);

  if (error) throw error;
}

export function startPresenceSession(options: PresenceSessionOptions): () => void {
  const selfChannel = supabase.channel(`presence:self:${options.userRole}`);
  const watcherChannel = supabase.channel(options.channelName);

  selfChannel.subscribe(async (status) => {
    if (status !== 'SUBSCRIBED') return;

    try {
      await markUserPresenceSeen(options.userId);
      await selfChannel.track({
        user_id: options.userId,
        vibe: options.userVibe ?? 'active',
        online_at: new Date().toISOString(),
      });
    } catch {
      options.onOfflineChange(true);
    }
  });

  watcherChannel
    .on('presence', { event: 'sync' }, () => {
      const state = watcherChannel.presenceState();
      const presences = Object.values(state).flat();
      options.onCountChange(presences.length);
      options.onOfflineChange(false);
    })
    .on('presence', { event: 'join' }, () => {
      options.onOfflineChange(false);
    })
    .subscribe((status) => {
      if (status === 'CLOSED' || status === 'CHANNEL_ERROR') {
        options.onOfflineChange(true);
      }
    });

  return () => {
    supabase.removeChannel(selfChannel);
    supabase.removeChannel(watcherChannel);
  };
}

