/**
 * Get school type display name by language
 */
export function getSchoolTypeLabel(type: SchoolType, language: 'en' | 'si' | 'ta' = 'en'): string {
  return SRI_LANKAN_SCHOOL_TYPES[type]?.[language] || type;
}

/**
 * Get section display name by language
 */
export function getSectionLabel(section: SectionType, language: 'en' | 'si' | 'ta' = 'en'): string {
  return SCHOOL_SECTIONS[section]?.[language] || section;
}

/**
 * Get grades for a section
 */
export function getGradesForSection(section: SectionType): number[] {
  const sec = SCHOOL_SECTIONS[section] as any;
  return sec?.grades || [];
}

/**
 * Determine which section a grade belongs to
 */
export function getSectionForGrade(gradeNumber: number): SectionType | null {
  if (gradeNumber >= 1 && gradeNumber <= 5) return 'primary';
  if (gradeNumber >= 6 && gradeNumber <= 9) return 'junior';
  if (gradeNumber >= 10 && gradeNumber <= 13) return 'senior';
  return null;
}

﻿import { useMemo } from 'react';
import { usePermissions } from '../logic/permissions/hooks/usePermissions';
import type { AuthorityTier } from '../types/Authority';
import { useFeatureAccess } from './useFeatureAccess';

export interface AuthorityFeatures {
  // Visibility flags
  showClassroom: boolean;
  showCommunity: boolean;
  showLibrary: boolean;
  showSelf: boolean;
  showManagement: boolean;

  // Action flags
  canCreateContent: boolean;
  canInteract: boolean;
  canManageSchool: boolean;

  // Status flags
  isAnonymous: boolean;
  authority: AuthorityTier | null;
}

/**
 * Hook to provide authority-specific feature sets, accounting for anonymity.
 * This should be the primary interface for UI-level feature gating.
 */
export function useAuthorityFeatures(): AuthorityFeatures {
  const { can, context } = usePermissions();
  const isUserAnonymous = !context.userId;
  const { isGuest } = useFeatureAccess();

  // Combining store anonymity with feature-level guest status
  const isAnonymous = isUserAnonymous || isGuest;
  const authority = context.authority;

  const features = useMemo(() => {
    // Base features for everyone
    const base = {
      showClassroom: true,
      showCommunity: true,
      showLibrary: true,
      showSelf: true,
      showManagement: false,
      canCreateContent: !isAnonymous,
      canInteract: !isAnonymous,
      canManageSchool: false,
      isAnonymous,
      authority,
    };

    // Authority-specific overrides
    switch (authority) {
      case 'founder':
      case 'admin':
      case 'developer':
      case 'principal':
        return {
          ...base,
          showManagement: true,
          canManageSchool: true,
          canCreateContent: true,
        };
      case 'teacher':
        return {
          ...base,
          canCreateContent: true,
        };
      case 'student':
        return {
          ...base,
          canCreateContent: false, // Students usually interact but don't "create" core objects
          canInteract: true,
        };
      default:
        // Guests or undefined authority
        return {
          ...base,
          showManagement: false,
          canCreateContent: false,
          canInteract: false,
        };
    }
  }, [authority, isAnonymous]);

  return features;
}

﻿import { useCallback, useEffect, useState } from 'react';
import { type BanyanStage, naturePathsAPI } from '../api/naturePaths';
import { usePermissions } from '../logic/permissions/hooks/usePermissions';

/**
 * useBanyanGrowth
 *
 * A hook to fetch and manage a teacher's or principal's Banyan growth state.
 */
export function useBanyanGrowth() {
  const { context } = usePermissions();
  const userId = context.userId;
  const [banyan, setBanyan] = useState<{
    banyan_stage: BanyanStage;
    peer_mentored_count: number;
    circles_facilitated_count: number;
  } | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const refreshBanyan = useCallback(async () => {
    if (!userId) return;
    setIsLoading(true);
    try {
      const state = await naturePathsAPI.getBanyanState(userId);
      setBanyan(state);
    } catch (error) {
      console.error('[useBanyanGrowth] Error fetching Banyan state:', error);
    } finally {
      setIsLoading(false);
    }
  }, [userId]);

  useEffect(() => {
    refreshBanyan();
  }, [refreshBanyan]);

  return {
    banyan,
    isLoading,
    refreshBanyan,
  };
}

