    description: string;
  };
  academic: {
    sectionId: string;
    gradeId: string;
    subject: string;
    syllabusId: string;
  };
  aesthetics: {
    themeId: string;
    classType: 'own' | 'subject';
  };
}

const initialState: ClassroomCreationState = {
  step: 1,
  details: {
    name: '',
    handle: '',
    description: '',
  },
  academic: {
    sectionId: '',
    gradeId: '',
    subject: '',
    syllabusId: 'legacy',
  },
  aesthetics: {
    themeId: 'saffron',
    classType: 'own',
  },
};

export function useClassroomCreation() {
  const [state, setState] = useState<ClassroomCreationState>(initialState);
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    const loadState = async () => {
      try {
        const savedState = await AsyncStorage.getItem(PERSISTENCE_KEY);
        if (savedState) {
          setState(JSON.parse(savedState));
        }
      } catch (e) {
        console.error('Failed to load classroom creation state', e);
      } finally {
        setIsLoaded(true);
      }
    };
    loadState();
  }, []);

  useEffect(() => {
    if (isLoaded) {
      AsyncStorage.setItem(PERSISTENCE_KEY, JSON.stringify(state));
    }
  }, [state, isLoaded]);

  const updateStep = (step: number) => setState((prev) => ({ ...prev, step }));

  const updateDetails = (details: Partial<ClassroomCreationState['details']>) =>
    setState((prev) => ({ ...prev, details: { ...prev.details, ...details } }));

  const updateAcademic = (academic: Partial<ClassroomCreationState['academic']>) =>
    setState((prev) => ({
      ...prev,
      academic: { ...prev.academic, ...academic },
    }));

  const updateAesthetics = (aesthetics: Partial<ClassroomCreationState['aesthetics']>) =>
    setState((prev) => ({
      ...prev,
      aesthetics: { ...prev.aesthetics, ...aesthetics },
    }));

  const resetProgress = async () => {
    await AsyncStorage.removeItem(PERSISTENCE_KEY);
    setState(initialState);
  };

  return {
    state,
    isLoaded,
    updateStep,
    updateDetails,
    updateAcademic,
    updateAesthetics,
    resetProgress,
  };
}

import { useCallback, useEffect, useState } from 'react';
import { type DeviceAccountRecord, deviceAccounts } from '../accounts/deviceAccounts';

export type { DeviceAccountRecord };

export function useDeviceAccounts() {
  const [accounts, setAccounts] = useState<DeviceAccountRecord[]>([]);
  const [activeAccountId, setActiveAccountId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [busyAccountId, setBusyAccountId] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    const [nextAccounts, nextActiveId] = await Promise.all([
      deviceAccounts.list(),
      deviceAccounts.getActiveAccountId(),
    ]);
    setAccounts(nextAccounts);
    setActiveAccountId(nextActiveId);
  }, []);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        const [nextAccounts, nextActiveId] = await Promise.all([
          deviceAccounts.list(),
          deviceAccounts.getActiveAccountId(),
        ]);

        if (cancelled) return;
        setAccounts(nextAccounts);
        setActiveAccountId(nextActiveId);
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  const switchAccount = useCallback(
    async (accountId: string) => {
      setBusyAccountId(accountId);
      try {
        await deviceAccounts.switchTo(accountId);
        await refresh();
      } finally {
        setBusyAccountId(null);
      }
    },
    [refresh],
  );

  const removeAccount = useCallback(
    async (accountId: string) => {
      setBusyAccountId(accountId);
      try {
        await deviceAccounts.removeAccount(accountId);
        await refresh();
      } finally {
        setBusyAccountId(null);
      }
    },
    [refresh],
  );

  const signOutCurrentAccount = useCallback(async () => {
    const currentId = activeAccountId;
    setBusyAccountId(currentId);
    try {
      await deviceAccounts.signOutCurrentAccount();
      await refresh();
    } finally {
      setBusyAccountId(null);
    }
  }, [activeAccountId, refresh]);

  const signOutAllAccounts = useCallback(async () => {
    setBusyAccountId(activeAccountId);
    try {
      await deviceAccounts.signOutAllAccounts();
      await refresh();
    } finally {
      setBusyAccountId(null);
    }
  }, [activeAccountId, refresh]);

  return {
    accounts,
    activeAccountId,
    loading,
    busyAccountId,
    refresh,
    switchAccount,
    removeAccount,
    signOutCurrentAccount,
    signOutAllAccounts,
  };
}

import { useCallback, useEffect, useState } from 'react';
import { useMutationQueue } from '../lib/sync/useMutationQueue';
import {
  type DeviceSecurityEvent,
  type DeviceSecuritySession,
  type DeviceTrustSummary,
  deviceTrustAPI,
} from '../api/deviceTrust';
import { isQueuedDeviceSecurityMutation } from '../lib/sync/deviceSecurityIntents';

export function useDeviceSecurity(limit = 50) {
  const pendingSecurityMutations = useMutationQueue((state) =>
    state.queue.filter(isQueuedDeviceSecurityMutation),
  );
  const [devices, setDevices] = useState<DeviceTrustSummary[]>([]);
  const [events, setEvents] = useState<DeviceSecurityEvent[]>([]);
  const [sessions, setSessions] = useState<DeviceSecuritySession[]>([]);
  const [currentDevice, setCurrentDevice] = useState<DeviceTrustSummary | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    setError(null);
    const [nextDevices, nextEvents, nextSessions, nextCurrentDevice] = await Promise.all([
      deviceTrustAPI.listMyDevices(),
      deviceTrustAPI.listMySecurityAuditEvents(limit),
      deviceTrustAPI.listMySecuritySessions(limit),
      deviceTrustAPI.getCurrentDeviceTrust(),
    ]);

    setDevices(nextDevices);
    setEvents(nextEvents);
    setSessions(nextSessions);
    setCurrentDevice(nextCurrentDevice);
  }, [limit]);

  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        await refresh();
      } catch (nextError) {
        if (!cancelled) {
          const message =
            nextError instanceof Error ? nextError.message : 'Failed to load device security data.';
          setError(message);
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [refresh]);

  return {
    devices,
    events,
    sessions,
    currentDevice,
    loading,
    error,
    refresh,
    pendingSecuritySyncCount: pendingSecurityMutations.length,
    unlinkDevice: deviceTrustAPI.unlinkMyDevice,
    revokeSession: deviceTrustAPI.revokeMySecuritySession,
    revokeOtherSessions: deviceTrustAPI.revokeMyOtherSecuritySessions,
  };
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { api } from '../api'; // Use common API
import type { EntityInstance, EntityMode, EntityType } from '../logic/entities/entity-protocol';

export interface UseEntityOptions {
  type: EntityType;
  id?: string;
  mode?: EntityMode;
  initialData?: any;
}

export function useEntity<T = any>(options: UseEntityOptions | EntityType, legacyId?: string) {
  // Handle both new object-based and legacy positional arguments
  const config =
    typeof options === 'string'
      ? { type: options, id: legacyId, mode: 'view' as EntityMode }
      : options;

  const { type, id, mode = 'view' } = config;

  const [instance, setInstance] = useState<EntityInstance<T> | null>(null);
  const [isLoading, setIsLoading] = useState(!!id && mode !== 'create');
  const [error, setError] = useState<Error | null>(null);

  const refresh = useCallback(async () => {
    if (!id || mode === 'create') return;
    setIsLoading(true);
    try {
      // In a real app, this would fetch from API based on type
      const data = await (api as any)[type].get(id);
      setInstance({
        id,
        type,
        definition: { type } as any, // Should come from a registry
        data,
      });
      setIsLoading(false);
    } catch (err) {
      setError(err as Error);
      setIsLoading(false);
    }
  }, [type, id, mode]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const create = useCallback(
    async (data: T) => {
      setIsLoading(true);
      try {
        const result = await (api as any)[type].create(data);
        setIsLoading(false);
        return result;
      } catch (err) {
        setError(err as Error);
        setIsLoading(false);
        throw err;
      }
    },
    [type],
  );

  const updateInstance = useCallback(
    async (updates: Partial<T>) => {
      if (!id) return null;
      setIsLoading(true);
      try {
        const result = await (api as any)[type].update(id, updates);
        setInstance((prev) => (prev ? { ...prev, data: { ...prev.data, ...result } } : null));
        setIsLoading(false);
        return result;
      } catch (err) {
        setError(err as Error);
        setIsLoading(false);
        throw err;
      }
    },
    [type, id],
  );

  return useMemo(
    () => ({
      instance,
      updateInstance,
      create,
      isLoading,
      error,
      refresh,
    }),
    [instance, updateInstance, create, isLoading, error, refresh],
  );
}

import { useEffect, useState } from 'react';
import type { FormManager, FormState } from '../logic/forms/form-manager';

/**
 * A React hook to bridge the framework-agnostic FormManager to React/React Native.
 *
 * @param manager - An instance of FormManager
 * @returns The current form state
 *
 * @example
 * const manager = new FormManager(config);
 * const state = useForm(manager);
 */
export function useForm<T extends Record<string, any>>(manager: FormManager<T>): FormState<T> {
  // Use lazy initialization to get the current state from the manager
  const [state, setState] = useState<FormState<T>>(() => manager.getState());

  useEffect(() => {
    // Force sync when manager dependency changes
    setState(manager.getState());

    const unsubscribe = manager.subscribe((newState) => {
      // Use functional update to ensure we always have the latest state reference
      setState(() => ({ ...newState }));
    });

    return () => {
      unsubscribe();
    };
  }, [manager]);

  return state;
}

