import { useQuery } from '@tanstack/react-query';
import { useMemo } from 'react';
import { supabase } from '../api/supabase';
import { usePermissions } from '../logic/permissions/hooks/usePermissions';
import { applyTemporalFilter } from '../logic/utils/temporalUtils';
import { useTemporalStore } from '../store/useTemporalStore';

export interface JourneyEvent {
  id: string;
  timestamp: string;
  type: 'mood' | 'journal' | 'growth' | 'reward' | 'moment' | 'impact' | 'system';
  title: string;
  description?: string;
  metadata?: any;
  accentColor?: string;
}

export interface HolisticView {
  date: string;
  events: JourneyEvent[];
  summary: string;
}

/**
 * useJourneyHistory
 *
 * Aggregates role-specific feature history into a consolidated stream.
 * Supports Daily/Weekly holistic views.
 */
export function useJourneyHistory(_section?: string, _feature?: string) {
  const { context } = usePermissions();
  const { userId, authority } = context;
  const { phase, viewDate, viewScale, timelineFocus } = useTemporalStore();

  // Fetch Mood Logs for the current context
  const { data: moodEvents = [], isLoading: moodLoading } = useQuery({
    queryKey: ['journey_history_mood', userId, viewDate, viewScale],
    queryFn: async () => {
      if (!userId) return [];

      let query = supabase.from('mood_logs').select('*').eq('user_id', userId);
      query = applyTemporalFilter(query, {
        column: 'created_at',
        mode: 'event_time',
        capability: 'event_stream',
      });

      const { data } = await query.order('created_at', { ascending: false });
      return (data || []).map(
        (item) =>
          ({
            id: item.id,
            timestamp: item.created_at,
            type: 'mood',
            title: `Mood: ${item.mood_type}`,
            description: item.note,
            accentColor: '#F6BF8C',
          }) as JourneyEvent,
      );
    },
    enabled: !!userId,
  });

  // Fetch Journal Entries
  const { data: journalEvents = [], isLoading: journalLoading } = useQuery({
    queryKey: ['journey_history_journal', userId, viewDate, viewScale],
    queryFn: async () => {
      if (!userId) return [];
      let query = supabase.from('journal_entries').select('*').eq('user_id', userId);
      query = applyTemporalFilter(query, {
        column: 'created_at',
        mode: 'event_time',
        capability: 'event_stream',
      });

      const { data } = await query.order('created_at', { ascending: false });
      return (data || []).map(
        (item) =>
          ({
            id: item.id,
            timestamp: item.created_at,
            type: 'journal',
            title: item.title || 'Untitled Entry',
            description: item.content?.substring(0, 100),
            accentColor: '#10B981',
          }) as JourneyEvent,
      );
    },
    enabled: !!userId,
  });

  const { data: growthEvents = [], isLoading: growthLoading } = useQuery({
    queryKey: ['journey_history_growth', userId, viewDate, viewScale],
    queryFn: async () => {
      if (!userId) return [];

      let query = supabase
        .from('user_growth_state_versions')
        .select('id, operation, recorded_at, snapshot')
        .eq('user_id', userId);

      query = applyTemporalFilter(query, {
        column: 'recorded_at',
        mode: 'event_time',
        capability: 'audit_history',
      });

      const { data } = await query.order('recorded_at', { ascending: false });
      return (data || []).map(
        (item) =>
          ({
            id: item.id,
            timestamp: item.recorded_at,
            type: 'growth',
            title: `Growth moved through ${(item.snapshot as any)?.bhumi_stage ?? 'journey'}`,
            description:
              [
                (item.snapshot as any)?.banyan_stage
                  ? `Banyan ${(item.snapshot as any).banyan_stage}`
                  : null,
                (item.snapshot as any)?.river_stage
                  ? `River ${(item.snapshot as any).river_stage}`
                  : null,
                (item.snapshot as any)?.crystal_tier
                  ? `Crystal ${(item.snapshot as any).crystal_tier}`
                  : null,
              ]
                .filter(Boolean)
                .join(' " ') || 'Growth state updated',
            metadata: item.snapshot as any,
            accentColor: '#D97706',
          }) as JourneyEvent,
      );
    },
    enabled: !!userId,
  });

  const { data: rewardEvents = [], isLoading: rewardLoading } = useQuery({
    queryKey: ['journey_history_rewards', userId, viewDate, viewScale],
    queryFn: async () => {
      if (!userId) return [];

      let query = supabase
        .from('user_rewards_versions')
        .select('id, operation, recorded_at, snapshot')
        .eq('user_id', userId);

      query = applyTemporalFilter(query, {
        column: 'recorded_at',
        mode: 'event_time',
        capability: 'audit_history',
      });

      const { data } = await query.order('recorded_at', { ascending: false });
      return (data || []).map(
        (item) =>
          ({
            id: item.id,
            timestamp: item.recorded_at,
            type: 'reward',
            title: `Rewards ${item.operation}`,
            description: `${(item.snapshot as any)?.points ?? 0} growth points " ${Array.isArray((item.snapshot as any)?.badges) ? (item.snapshot as any).badges.length : 0} badges`,
            metadata: item.snapshot as any,
            accentColor: '#7C3AED',
          }) as JourneyEvent,
      );
    },
    enabled: !!userId,
  });

  const { data: momentEvents = [], isLoading: momentLoading } = useQuery({
    queryKey: ['journey_history_moments', userId, viewDate, viewScale],
    queryFn: async () => {
      if (!userId) return [];

      let query = supabase
        .from('whispered_moments')
        .select('id, moment_key, moment_name_en, moment_name_si, awarded_at')
        .eq('user_id', userId);

      query = applyTemporalFilter(query, {
        column: 'awarded_at',
        mode: 'event_time',
        capability: 'event_stream',
      });

      const { data } = await query.order('awarded_at', { ascending: false });
      return (data || []).map(
        (item) =>
          ({
            id: item.id,
            timestamp: item.awarded_at,
            type: 'moment',
            title: item.moment_name_en || item.moment_key,
            description: item.moment_name_si,
            metadata: {
              key: item.moment_key,
              name_en: item.moment_name_en,
              name_si: item.moment_name_si,
            },
            accentColor: '#0EA5E9',
          }) as JourneyEvent,
      );
    },
    enabled: !!userId,
  });

  // Consolidate and Sort
  const events = useMemo(() => {
    const all: JourneyEvent[] = [];
    if (timelineFocus === 'all' || timelineFocus === 'mood') all.push(...moodEvents);
    if (timelineFocus === 'all' || timelineFocus === 'journal') all.push(...journalEvents);
    if (timelineFocus === 'all' || timelineFocus === 'growth' || timelineFocus === 'journey')
      all.push(...growthEvents);
    if (timelineFocus === 'all' || timelineFocus === 'reward' || timelineFocus === 'journey')
      all.push(...rewardEvents);
    if (timelineFocus === 'all' || timelineFocus === 'moment' || timelineFocus === 'journey')
      all.push(...momentEvents);

    return all.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [moodEvents, journalEvents, growthEvents, rewardEvents, momentEvents, timelineFocus]);

  // Holistic Aggregation
  const holisticView = useMemo(() => {
    if (viewScale === 'day') {
      return {
        date: viewDate,
        events,
        summary:
          events.length > 0
            ? `You recorded ${events.length} history points today.`
            : 'No history points found for this day.',
      };
    }

    if (viewScale === 'week') {
      return {
        date: viewDate,
        events,
        summary: `Weekly overview: ${events.length} activities captured.`,
      };
    }

    if (viewScale === 'month') {
      return {
        date: viewDate,
        events,
        summary: `Monthly history: ${events.length} milestones identified.`,
      };
    }

    return {
      date: viewDate,
      events,
      summary: `Yearly journey: ${events.length} signature history points preserved.`,
    };
  }, [events, viewScale, viewDate]);

  return {
    events,
    holisticView,
    isLoading: moodLoading || journalLoading || growthLoading || rewardLoading || momentLoading,
    authority,
    currentScale: viewScale,
    phase,
    timelineFocus,
  };
}

import { useState } from 'react';
import { supabase } from '../api/supabase';
import { usePermissions } from '../logic/permissions/hooks/usePermissions';
import { useTemporalStore } from '../store/useTemporalStore';
import { useTracking } from './useTracking';

export interface SnapshotMoment {
  id: string;
  user_id: string;
  snapshot_date: string;
  label: string;
  metadata: any;
  created_at: string;
}

/**
 * useManualSnapshot
 *
 * Capability to explicitly snapshot the current temporal context
 * into a persistent moment.
 */
export function useManualSnapshot() {
  const { context } = usePermissions();
  const userId = context.userId;
  const { viewDate } = useTemporalStore();
  const { trackSnapshot } = useTracking();
  const [isSaving, setIsSaving] = useState(false);

  /**
   * Captures a snapshot of the current temporal state.
   */
  const takeSnapshot = async (label: string = 'Snapshot Moment', additionalMetadata: any = {}) => {
    if (!userId) return null;

    setIsSaving(true);
    try {
      // In a real implementation, we would aggregate current state of all features here.
      // For now, we capture the core temporal context and label.
      const { data, error } = await supabase
        .from('snapshot_moments')
        .insert([
          {
            user_id: userId,
            // Keep database writes compatible with the current schema.
            resonance_date: viewDate,
            label,
            metadata: {
              ...additionalMetadata,
              captured_at: new Date().toISOString(),
            },
          },
        ])
        .select()
        .single();

      if (error) throw error;

      // Analytics
      trackSnapshot(label, viewDate);

      if (!data) return null;

      return {
        ...data,
        snapshot_date: data.resonance_date,
      } as SnapshotMoment;
    } catch (error) {
      console.error('Failed to capture snapshot:', error);
      return null;
    } finally {
      setIsSaving(false);
    }
  };

  return {
    takeSnapshot,
    isSaving,
  };
}

import * as FileSystem from 'expo-file-system';
import * as Sharing from 'expo-sharing';
import { useCallback, useEffect, useState } from 'react';
import { Platform } from 'react-native';

export type DownloadState = 'idle' | 'downloading' | 'ready' | 'error';

interface UseMediaDownloaderOptions {
  resourceId: string;
  url: string;
  mimeType?: string;
}

/**
 * useMediaDownloader - Handles local caching and native handoff for remote resources.
 */
export function useMediaDownloader({ resourceId, url, mimeType }: UseMediaDownloaderOptions) {
  const [downloadState, setDownloadState] = useState<DownloadState>('idle');
  const [progress, setProgress] = useState(0);
  const [localUri, setLocalUri] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const extension = mimeType === 'application/pdf' ? 'pdf' : url.split('.').pop() || 'tmp';
  const fileName = `gurudevi_${resourceId}.${extension}`;
  const localPath =
    ((FileSystem as any).cacheDirectory ?? (FileSystem as any).documentDirectory) + fileName;

  const checkCached = useCallback(async () => {
    if (Platform.OS === 'web') return;
    try {
      const info = await FileSystem.getInfoAsync(localPath);
      if (info.exists) {
        setLocalUri(localPath);
        setDownloadState('ready');
      }
    } catch {
      // not cached
    }
  }, [localPath]);

  useEffect(() => {
    checkCached();
  }, [checkCached]);

  const startDownload = useCallback(async () => {
    if (Platform.OS === 'web') {
      // For web, just open the URL in a new tab or trigger browser download
      window.open(url, '_blank');
      return;
    }

    if (!url) {
      setErrorMsg('No URL provided for this document.');
      setDownloadState('error');
      return;
    }

    setDownloadState('downloading');
    setProgress(0);
    setErrorMsg(null);

    try {
      const downloadResumable = FileSystem.createDownloadResumable(
        url,
        localPath,
        {},
        ({ totalBytesWritten, totalBytesExpectedToWrite }) => {
          if (totalBytesExpectedToWrite > 0) {
            setProgress(totalBytesWritten / totalBytesExpectedToWrite);
          }
        },
      );
      const result = await downloadResumable.downloadAsync();
      if (result?.uri) {
        setLocalUri(result.uri);
        setDownloadState('ready');
      } else {
        throw new Error('Download returned no URI');
      }
    } catch (e: any) {
      setErrorMsg(e?.message ?? 'Download failed');
      setDownloadState('error');
    }
  }, [url, localPath]);

  const openInNativeViewer = useCallback(async () => {
    if (Platform.OS === 'web') {
      window.open(url, '_blank');
      return;
    }

    const target = localUri;
    if (!target) return;
    const canShare = await Sharing.isAvailableAsync();
    if (canShare) {
      await Sharing.shareAsync(target, { mimeType });
    }
  }, [localUri, url, mimeType]);

  return {
    downloadState,
    progress,
    localUri,
    errorMsg,
    startDownload,
    openInNativeViewer,
    reset: () => {
      setDownloadState('idle');
      setLocalUri(null);
    },
  };
}

