/**
 * useNotifications  Real notification data for NotificationDrawer.
 *
 * Fetches the 20 most recent notifications for the current user.
 * Provides `markAsRead` and `markAllRead` helpers.
 * Gracefully degrades on DB error (returns empty array).
 */

import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '../api/supabase';

export interface AppNotification {
  id: string;
  type: string;
  title: string;
  body: string | null;
  is_read: boolean;
  reference_id: string | null;
  reference_type: string | null;
  created_at: string;
}

export interface UseNotificationsResult {
  notifications: AppNotification[];
  unreadCount: number;
  isLoading: boolean;
  markAsRead: (id: string) => Promise<void>;
  markAllRead: () => Promise<void>;
  refresh: () => void;
}

export function useNotifications(userId: string | null | undefined): UseNotificationsResult {
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isLoading, setIsLoading] = useState(false);

  const loadUnreadCount = useCallback(async () => {
    if (!userId) return;
    try {
      const { count, error } = await supabase
        .from('notifications')
        .select('*', { count: 'exact', head: true })
        .eq('user_id', userId)
        .eq('is_read', false);

      if (!error && count !== null) {
        setUnreadCount(count);
      }
    } catch {
      /* degrade */
    }
  }, [userId]);

  const load = useCallback(async () => {
    if (!userId) return;
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('notifications')
        .select('id, type, title, body, is_read, reference_id, reference_type, created_at')
        .eq('user_id', userId)
        .order('created_at', { ascending: false })
        .limit(20);

      if (!error && data) {
        setNotifications(data as AppNotification[]);
        await loadUnreadCount();
      }
    } catch {
      // Silently degrade  drawer shows empty state rather than crashing
    } finally {
      setIsLoading(false);
    }
  }, [userId, loadUnreadCount]);

  useEffect(() => {
    load();
  }, [load]);

  // Real-time subscription  new notifications arrive instantly without polling
  useEffect(() => {
    if (!userId) return;

    const channel = supabase
      .channel(`notifications:${userId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'notifications',
          filter: `user_id=eq.${userId}`,
        },
        async (payload) => {
          const incoming = payload.new as AppNotification;
          setNotifications((prev) => [incoming, ...prev].slice(0, 20));
          if (!incoming.is_read) {
            setUnreadCount((prev) => prev + 1);
          }
        },
      )
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'notifications',
          filter: `user_id=eq.${userId}`,
        },
        async (payload) => {
          const updated = payload.new as AppNotification;
          const _old = payload.old as AppNotification | undefined;

          setNotifications((prev) =>
            prev.map((n) => (n.id === updated.id ? { ...n, is_read: updated.is_read } : n)),
          );

          // Update unread count if is_read changed
          if (updated.is_read) {
            // Recalculate accurately to avoid desync
            await loadUnreadCount();
          }
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [userId, loadUnreadCount]);

  const markAsRead = useCallback(
    async (id: string) => {
      if (!userId) return;
      await supabase
        .from('notifications')
        .update({ is_read: true })
        .eq('id', id)
        .eq('user_id', userId);

      setNotifications((prev) => prev.map((n) => (n.id === id ? { ...n, is_read: true } : n)));
      await loadUnreadCount();
    },
    [userId, loadUnreadCount],
  );

  const markAllRead = useCallback(async () => {
    if (!userId) return;
    await supabase
      .from('notifications')
      .update({ is_read: true })
      .eq('user_id', userId)
      .eq('is_read', false);

    setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true })));
    setUnreadCount(0);
  }, [userId]);

  return useMemo(
    () => ({
      notifications,
      unreadCount,
      isLoading,
      markAsRead,
      markAllRead,
      refresh: load,
    }),
    [notifications, unreadCount, isLoading, markAsRead, markAllRead, load],
  );
}

/**
 * usePendingActions  Real pending work for the teacher's PulseDashboard.
 *
 * Returns two lists:
 *   - attendancePending: classrooms where today's attendance has NOT been recorded yet
 *   - gradingPending:    assignments whose due_date is today-or-past and that have at
 *                        least one submission without a grade
 *
 * Both lists are capped at 5 items so the dashboard stays concise.
 * Gracefully degrades on any DB error  returns empty arrays rather than throwing.
 */

import { useCallback, useEffect, useState } from 'react';
import { supabase } from '../api/supabase';

export interface PendingAttendanceItem {
  classroomId: string;
  classroomName: string;
}

export interface PendingGradingItem {
  assignmentId: string;
  assignmentTitle: string;
  classroomId: string;
  classroomName: string;
  ungradedCount: number;
}

export interface PendingActionsResult {
  attendancePending: PendingAttendanceItem[];
  gradingPending: PendingGradingItem[];
  isLoading: boolean;
  refresh: () => void;
}

const MAX_ITEMS = 5;

export function usePendingActions(teacherId: string | null | undefined): PendingActionsResult {
  const [attendancePending, setAttendancePending] = useState<PendingAttendanceItem[]>([]);
  const [gradingPending, setGradingPending] = useState<PendingGradingItem[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const load = useCallback(async () => {
    if (!teacherId) return;
    setIsLoading(true);
    // Use local date to avoid timezone mismatch (e.g. UTC vs Asia/Colombo)
    const now = new Date();
    const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    const todayEnd = `${today}T23:59:59`;

    try {
      //  1. Classrooms owned by this teacher
      const { data: classrooms, error: clsErr } = await supabase
        .from('classrooms')
        .select('id, name')
        .eq('teacher_id', teacherId)
        .limit(20);

      if (clsErr || !classrooms?.length) {
        setAttendancePending([]);
        setGradingPending([]);
        return;
      }

      const classroomIds = classrooms.map((c) => c.id);

      //  2. Classrooms that already have attendance today
      const { data: markedToday } = await supabase
        .from('attendance')
        .select('classroom_id')
        .in('classroom_id', classroomIds)
        .eq('date', today);

      const markedIds = new Set((markedToday ?? []).map((r: any) => r.classroom_id));

      const pending = classrooms
        .filter((c) => !markedIds.has(c.id))
        .slice(0, MAX_ITEMS)
        .map((c) => ({ classroomId: c.id, classroomName: c.name }));

      setAttendancePending(pending);

      //  3. Assignments due today or overdue with ungraded submissions
      const { data: assignments } = await supabase
        .from('assignments')
        .select('id, title, classroom_id, due_date')
        .in('classroom_id', classroomIds)
        .lte('due_date', todayEnd)
        .limit(30);

      if (!assignments?.length) {
        setGradingPending([]);
        return;
      }

      const assignmentIds = assignments.map((a) => a.id);

      // Submissions with no grade (graded_at IS NULL or grade IS NULL)
      const { data: ungraded } = await supabase
        .from('submissions')
        .select('assignment_id')
        .in('assignment_id', assignmentIds)
        .is('graded_at', null);

      if (!ungraded?.length) {
        setGradingPending([]);
        return;
      }

      // Count ungraded per assignment
      const countMap: Record<string, number> = {};
      for (const s of ungraded) {
        countMap[s.assignment_id] = (countMap[s.assignment_id] ?? 0) + 1;
      }

      // Build classroom name lookup
      const clsMap: Record<string, string> = {};
      for (const c of classrooms) clsMap[c.id] = c.name;

      const pendingGrading = assignments
        .filter((a) => countMap[a.id])
        .slice(0, MAX_ITEMS)
        .map((a) => ({
          assignmentId: a.id,
          assignmentTitle: a.title,
          classroomId: a.classroom_id,
          classroomName: clsMap[a.classroom_id] ?? '',
          ungradedCount: countMap[a.id] ?? 0,
        }));

      setGradingPending(pendingGrading);
    } catch {
      // Silently degrade  PulseDashboard shows nothing rather than crashing
      setAttendancePending([]);
      setGradingPending([]);
    } finally {
      setIsLoading(false);
    }
  }, [teacherId]);

  useEffect(() => {
    load();
  }, [load]);

  return { attendancePending, gradingPending, isLoading, refresh: load };
}

import { useCallback, useEffect, useState } from 'react';
import type { PendingGateAction } from '../lib/pendingGateAction';
import {
  clearPendingGateAction,
  getPendingGateAction,
  setPendingGateAction,
} from '../lib/pendingGateAction';

export interface UsePendingGateActionResult {
  action: PendingGateAction | null;
  isLoading: boolean;
  refresh: () => Promise<void>;
  set: (action: PendingGateAction) => Promise<void>;
  clear: () => Promise<void>;
}

export function usePendingGateAction(): UsePendingGateActionResult {
  const [action, setActionState] = useState<PendingGateAction | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const refresh = useCallback(async () => {
    setIsLoading(true);
    const next = await getPendingGateAction();
    setActionState(next);
    setIsLoading(false);
  }, []);

  const set = useCallback(async (next: PendingGateAction) => {
    await setPendingGateAction(next);
    setActionState(next);
  }, []);

  const clear = useCallback(async () => {
    await clearPendingGateAction();
    setActionState(null);
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  return { action, isLoading, refresh, set, clear };
}

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { identityAPI } from '../api/identity';
import { rewardsAPI } from '../api/rewards';
import { useTemporalStore } from '../store/useTemporalStore';

/**
 * Hook for managing user rewards, points, and milestones.
 * Provides real-time updates and mutations for adding points.
 */
export function useRewards(
  options: { userId?: string; includeHistory?: boolean; historyLimit?: number } = {},
) {
  const queryClient = useQueryClient();
  const [userId, setUserId] = useState<string | null>(null);
  const viewDate = useTemporalStore((state) => state.viewDate);
  const viewScale = useTemporalStore((state) => state.viewScale);
  const phase = useTemporalStore((state) => state.phase);

  useEffect(() => {
    const getUserId = async () => {
      const internalId = options.userId || (await identityAPI.getMyInternalId());
      if (internalId) setUserId(internalId);
    };
    getUserId();
  }, [options.userId]);

  // Fetch rewards data
  const {
    data: rewards,
    isLoading,
    error,
  } = useQuery({
    queryKey: ['rewards', userId, phase, viewDate, viewScale],
    queryFn: async () => {
      if (!userId) return null;
      const data =
        phase === 'past'
          ? await rewardsAPI.getRewardsAsOf(userId, viewDate)
          : await rewardsAPI.getRewards(userId);

      if (!data && !options.userId && phase === 'present') {
        return await rewardsAPI.initializeRewards(userId);
      }
      return data;
    },
    enabled: !!userId,
  });

  const { data: history = [] } = useQuery({
    queryKey: ['rewards_history', userId, viewDate, viewScale, options.historyLimit],
    queryFn: async () => {
      if (!userId) return [];
      if (phase === 'past') {
        return rewardsAPI.getRewardsRangeHistory(userId, viewDate, viewScale);
      }
      return rewardsAPI.getRewardsHistory(userId, options.historyLimit ?? 50);
    },
    enabled: !!userId && !!options.includeHistory,
  });

  // Mutation to add points
  const addPointsMutation = useMutation({
    mutationFn: ({ points }: { points: number }) => {
      if (!userId) throw new Error('User not authenticated');
      if (phase === 'past') throw new Error('Rewards are read-only in past view');
      return rewardsAPI.addPoints(userId, points);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['rewards', userId] });
    },
  });

  // Mutation to award badge
  const awardBadgeMutation = useMutation({
    mutationFn: ({ badge }: { badge: string }) => {
      if (!userId) throw new Error('User not authenticated');
      if (phase === 'past') throw new Error('Rewards are read-only in past view');
      return rewardsAPI.awardBadge(userId, badge);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['rewards', userId] });
    },
  });

  // Check achievements mutation
  const checkAchievementsMutation = useMutation({
    mutationFn: () => {
      if (phase === 'past') {
        return Promise.resolve({ updatedRewards: null, newAchievements: [] });
      }
      return userId
        ? rewardsAPI.checkAndAwardAchievements(userId)
        : Promise.resolve({ updatedRewards: null, newAchievements: [] });
    },
    onSuccess: (data) => {
      if (data.updatedRewards) {
        queryClient.setQueryData(['rewards', userId], data.updatedRewards);
        queryClient.invalidateQueries({ queryKey: ['rewards', userId] });
      }
    },
  });

  const addPoints = useCallback(
    (points: number) => addPointsMutation.mutateAsync({ points }),
    [addPointsMutation],
  );

  const awardBadge = useCallback(
    (badge: string) => awardBadgeMutation.mutateAsync({ badge }),
    [awardBadgeMutation],
  );

  const checkAchievements = useCallback(
    () => checkAchievementsMutation.mutateAsync(),
    [checkAchievementsMutation],
  );

  const trackAction = useCallback(
    async (
      actionType:
        | 'mood_log'
        | 'journal_entry'
        | 'library_upload'
        | 'community_post'
        | 'comment'
        | 'exploration',
    ) => {
      const pointsMap = {
        mood_log: 10,
        journal_entry: 20,
        library_upload: 50,
        community_post: 15,
        comment: 5,
        exploration: 0,
      };

      const points = pointsMap[actionType];
      if (points > 0) {
        await addPointsMutation.mutateAsync({ points });
      }

      // After every action, check for achievements
      return checkAchievementsMutation.mutateAsync();
    },
    [addPointsMutation, checkAchievementsMutation],
  );

  return useMemo(
    () => ({
      rewards: rewards || { points: 0, badges: [] },
      history,
      isLoading,
      error,
      addPoints,
      awardBadge,
      checkAchievements,
      trackAction,
      isUpdating:
        addPointsMutation.isPending ||
        awardBadgeMutation.isPending ||
        checkAchievementsMutation.isPending,
      newAchievements: checkAchievementsMutation.data?.newAchievements || [],
    }),
    [
      rewards,
      history,
      isLoading,
      error,
      addPoints,
      awardBadge,
      checkAchievements,
      trackAction,
      addPointsMutation.isPending,
      awardBadgeMutation.isPending,
      checkAchievementsMutation.isPending,
      checkAchievementsMutation.data?.newAchievements,
    ],
  );
}

import { useCallback, useState } from 'react';
import { v7 as uuidv7 } from 'uuid';
import { generateIdempotencyKey } from '../lib/sync/idempotency';
import { useMutationAuditLog } from '../lib/sync/MutationAuditLog';
import { useMutationQueue } from '../lib/sync/useMutationQueue';
import { networkManager } from '../logic/managers/NetworkManager';
import { useStore } from '../store/useStore';
import { DeltaResonance } from '../lib/sync/delta';

interface SafeMutationOptions<TData, TVariables> {
  mutationKey?: string; // Unique key for queueing (e.g. 'createPost')
  scope?: string; // Feature scope (e.g. 'community')
  onMutate?: (variables: TVariables) => void;
  onSuccess?: (data: TData | null, variables: TVariables) => void;
  onError?: (error: unknown, variables: TVariables, rollback?: () => void) => void;
  retryCount?: number;
  mutationType?: 'CREATE' | 'UPDATE' | 'DELETE' | 'CUSTOM' | 'PATCH';
  originalVariables?: TVariables; // For Delta-Resonance diffing
}

/**
 * useSafeMutation
 *
 * A high-resilience hook for performing write operations (POST/PATCH/DELETE).
 * Upgraded with:
 * - Resonant Audit Logging (Temporal memory)
 * - Deterministic Idempotency Keys (Spatial dedup)
 */
export function useSafeMutation<TData, TVariables>(
  mutationFn: (variables: TVariables) => Promise<TData>,
  options?: SafeMutationOptions<TData, TVariables>,
) {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const showToast = useStore((state) => state.showToast);
  const addToQueue = useMutationQueue((state) => state.addToQueue);
  const logAudit = useMutationAuditLog((state) => state.logEntry);

  const mutate = useCallback(
    async (variables: TVariables) => {
      setIsLoading(true);
      setError(null);

      // 1. Optimistic Update
      if (options?.onMutate) {
        options.onMutate(variables);
      }

      const executeRequest = async (attempt: number): Promise<TData> => {
        try {
          // Check connectivity
          const isConnected = await networkManager.isConnected();
          if (!isConnected) {
            throw new Error('OFFLINE_QUEUE');
          }

          return await mutationFn(variables);
        } catch (err: unknown) {
          if (err instanceof Error && err.message === 'OFFLINE_QUEUE') throw err;

          if (attempt < (options?.retryCount || 3)) {
            const delay = 2 ** attempt * 1000;
            await new Promise((resolve) => setTimeout(resolve, delay));
            return executeRequest(attempt + 1);
          }
          throw err;
        }
      };

      try {
        const result = await executeRequest(0);

        if (options?.onSuccess) {
          options.onSuccess(result, variables);
        }

        return result;
      } catch (err: unknown) {
        // Queue for later if network issue or offline signal
        const errorMessage = err instanceof Error ? err.message : String(err);
        if (errorMessage === 'OFFLINE_QUEUE' || errorMessage === 'Network request failed') {
          if (options?.mutationKey) {
            const mutationId = uuidv7(); // Upgraded to v7 for better DB locality
            const scope = options.scope || 'general';
            const name = options.mutationKey;

            // Fetch studentId from store for better salting
            const studentId = useStore.getState().user?.id;
            const idempotencyKey = await generateIdempotencyKey(scope, name, variables, studentId);

            // 1. Audit Entry (Temporal Birth)
            logAudit({
              id: mutationId,
              idempotencyKey,
              scope,
              name,
              status: 'queued',
              attempts: 0,
              queuedAt: Date.now(),
            });

            // 2. Queue for Persistence (with Delta-Resonance check)
            let finalVariables = variables;
            let finalType = options.mutationType || 'CREATE';

            if (options?.originalVariables && (finalType === 'UPDATE' || finalType === 'PATCH')) {
              const patch = DeltaResonance.diff(options.originalVariables, variables);
              if (patch.length > 0) {
                finalVariables = patch as any;
                finalType = 'PATCH';
              }
            }

            await addToQueue({
              name,
              scope,
              variables: finalVariables,
              type: finalType,
            });

            showToast('Saved to Outbox (Offline)', 'info');

            if (options?.onSuccess) {
              options.onSuccess(null, variables);
            }
            return null as TData;
          } else {
            console.warn('[SyncResonance] Cannot queue without mutationKey');
            showToast('Action failed (Offline)', 'error');
          }
        }

        setError(err instanceof Error ? err : new Error(errorMessage));
        if (options?.onError) options.onError(err, variables);
        else showToast(errorMessage || 'Action failed', 'error');

        throw err;
      } finally {
        setIsLoading(false);
      }
    },
    [mutationFn, options, showToast, addToQueue, logAudit],
  );

  return {
    mutate,
    isLoading,
    error,
  };
}

