  },
  location: {
    provinceId: '',
    districtId: '',
    city: '',
    address: '',
  },
  demographics: {
    studentType: '',
    religiousAffiliation: 'secular',
    studentCount: '',
  },
  hierarchy: {
    levels: [],
    gradeRange: { start: 1, end: 13 },
    sections: [],
  },
};

function creationReducer(state: SchoolCreationState, action: Action): SchoolCreationState {
  switch (action.type) {
    case 'SET_STATE':
      return action.payload;
    case 'UPDATE_STEP':
      return { ...state, step: action.payload };
    case 'UPDATE_BASIC_INFO':
      return { ...state, basicInfo: { ...state.basicInfo, ...action.payload } };
    case 'UPDATE_LOCATION':
      return { ...state, location: { ...state.location, ...action.payload } };
    case 'UPDATE_DEMOGRAPHICS':
      return {
        ...state,
        demographics: { ...state.demographics, ...action.payload },
      };
    case 'UPDATE_HIERARCHY':
      return { ...state, hierarchy: { ...state.hierarchy, ...action.payload } };
    case 'RESET':
      return initialState;
    default:
      return state;
  }
}

export function useSchoolCreation() {
  const [state, dispatch] = useReducer(creationReducer, initialState);
  const [isLoaded, setIsLoaded] = useState(false);

  // Load persisted state on mount
  useEffect(() => {
    async function loadState() {
      try {
        const savedState = await storage.getStringAsync(PERSISTENCE_KEY);
        if (savedState) {
          dispatch({ type: 'SET_STATE', payload: JSON.parse(savedState) });
        }
      } catch (e) {
        console.error('[useSchoolCreation] Load error:', e);
      } finally {
        setIsLoaded(true);
      }
    }
    loadState();
  }, []);

  // Persist state changes
  useEffect(() => {
    if (isLoaded) {
      storage.set(PERSISTENCE_KEY, JSON.stringify(state));
    }
  }, [state, isLoaded]);

  const updateStep = useCallback((step: number) => {
    dispatch({ type: 'UPDATE_STEP', payload: step });
  }, []);

  const updateBasicInfo = useCallback((info: Partial<SchoolCreationState['basicInfo']>) => {
    dispatch({ type: 'UPDATE_BASIC_INFO', payload: info });
  }, []);

  const updateLocation = useCallback((loc: Partial<SchoolCreationState['location']>) => {
    dispatch({ type: 'UPDATE_LOCATION', payload: loc });
  }, []);

  const updateDemographics = useCallback((demo: Partial<SchoolCreationState['demographics']>) => {
    dispatch({ type: 'UPDATE_DEMOGRAPHICS', payload: demo });
  }, []);

  const updateHierarchy = useCallback((hier: Partial<SchoolCreationState['hierarchy']>) => {
    dispatch({ type: 'UPDATE_HIERARCHY', payload: hier });
  }, []);

  const resetProgress = useCallback(async () => {
    storage.delete(PERSISTENCE_KEY);
    dispatch({ type: 'RESET' });
  }, []);

  return useMemo(
    () => ({
      state,
      isLoaded,
      updateStep,
      updateBasicInfo,
      updateLocation,
      updateDemographics,
      updateHierarchy,
      resetProgress,
    }),
    [
      state,
      isLoaded,
      updateStep,
      updateBasicInfo,
      updateLocation,
      updateDemographics,
      updateHierarchy,
      resetProgress,
    ],
  );
}

import { useEffect, useState } from 'react';
import { supabase } from '../api/supabase';

export interface StudentGoal {
  id: string;
  title: string;
  status: 'pending' | 'completed' | 'in_progress';
  target_date: string;
}

/**
 * useStudentGoals
 *
 * Fetches the user's focus goals for the Student role.
 */
export const useStudentGoals = (userId?: string) => {
  const [goals, setGoals] = useState<StudentGoal[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    if (!userId) return;

    const fetchGoals = async () => {
      setIsLoading(true);
      try {
        const { data } = await supabase
          .from('student_goals')
          .select('*')
          .eq('user_id', userId)
          .order('target_date', { ascending: true });

        if (data) setGoals(data);
      } catch (e) {
        console.error('[useStudentGoals] Error:', e);
      } finally {
        setIsLoading(false);
      }
    };

    fetchGoals();
  }, [userId]);

  return { goals, isLoading };
};

import { useCallback, useEffect, useMemo, useState } from 'react';
import { api } from '../api';
import type { Classroom, Student } from '../types';

/**
 * useTeacherClassroom: A sovereign hook for managing classroom data fetching and state.
 * Encapsulates the logic for loading a classroom's core data, students, and handling refreshes.
 */
export function useTeacherClassroom(classroomId: string) {
  const [classroom, setClassroom] = useState<Classroom | null>(null);
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const loadData = useCallback(async () => {
    if (!classroomId) return;

    setLoading(true);
    setError(null);

    try {
      const [classData, studentData] = await Promise.all([
        api.classrooms.getById(classroomId),
        api.classroomStudents.getAll(classroomId),
      ]);

      setClassroom(classData as Classroom);
      setStudents((studentData as unknown as Student[]) || []);
    } catch (err) {
      console.error('[useTeacherClassroom] Failed to load data:', err);
      setError(err instanceof Error ? err : new Error(String(err)));
    } finally {
      setLoading(false);
    }
  }, [classroomId]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const refreshStudents = useCallback(async () => {
    try {
      const studentData = await api.classroomStudents.getAll(classroomId);
      setStudents(studentData as unknown as Student[]);
    } catch (err) {
      console.error('[useTeacherClassroom] Failed to refresh students:', err);
    }
  }, [classroomId]);

  return useMemo(
    () => ({
      classroom,
      students,
      loading,
      error,
      refresh: loadData,
      refreshStudents,
    }),
    [classroom, students, loading, error, loadData, refreshStudents],
  );
}

import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useEffect, useState } from 'react';
import { identityAPI } from '../api/identity';
import { trackingAPI } from '../api/tracking';
import { trackEvent } from '../lib/monitoring/posthog';

/**
 * Hook for tracking feature discovery and exploration status.
 */
export function useTracking() {
  const queryClient = useQueryClient();
  const [userId, setUserId] = useState<string | null>(null);

  useEffect(() => {
    const getUserId = async () => {
      const myId = await identityAPI.getMyInternalId();
      if (myId) setUserId(myId);
    };
    getUserId();
  }, []);

  // Get explored features
  const { data: exploredFeatures = [], isLoading } = useQuery({
    queryKey: ['explored_features', userId],
    queryFn: () => (userId ? trackingAPI.getExploredFeatures(userId) : []),
    enabled: !!userId,
  });

  /**
   * Marks a feature as discovered.
   */
  const discoverFeature = async (featureName: string) => {
    if (!userId) return;

    // Optimistic check to avoid unnecessary API calls
    if (exploredFeatures.includes(featureName)) return;

    try {
      await trackingAPI.logFeatureUsage(userId, featureName);
      // PostHog Tracking
      trackEvent('feature_discovered', {
        feature_name: featureName,
        user_id: userId,
      });

      // Invalidate to refresh the explored list
      queryClient.invalidateQueries({
        queryKey: ['explored_features', userId],
      });
    } catch (error) {
      console.error(`Failed to track discovery for ${featureName}:`, error);
    }
  };

  /**
   * Checks if a feature has been discovered.
   */
  const isDiscovered = (featureName: string) => {
    return exploredFeatures.includes(featureName);
  };

  /**
   * Tracks a manual snapshot event.
   */
  const trackSnapshot = async (label: string, viewDate: string) => {
    if (!userId) return;

    trackEvent('manual_snapshot_captured', {
      label,
      snapshot_date: viewDate,
      user_id: userId,
    });
  };

  return {
    exploredFeatures,
    isLoading,
    discoverFeature,
    isDiscovered,
    trackSnapshot,
  };
}

