/**
 * requireAuth  Ensures the user is authenticated.
 */
export async function requireAuth() {
  const userId = await identityAPI.getMyInternalId();
  if (!userId) {
    throw new APIError('Not authenticated', 'UNAUTHENTICATED');
  }
  return userId;
}

/**
 * requireClassroomAccess  Ensures the user has a specific capability for a classroom.
 */
export async function requireClassroomAccess(classroomId: string, capability: string) {
  const userId = await requireAuth();

  // Fetch classroom context for POA check
  const { data: classroom, error } = await supabase
    .from('classrooms')
    .select('teacher_id, school_id')
    .eq('id', classroomId)
    .single();

  if (error || !classroom) {
    throw new APIError('Classroom not found', 'NOT_FOUND');
  }

  const ability = composeUserAbilities({
    userId,
    schoolId: classroom.school_id!,
  });

  if (
    !ability.can(capability as any, 'Classroom', {
      id: classroomId,
      teacher_id: classroom.teacher_id,
      school_id: classroom.school_id,
    } as any)
  ) {
    throw new APIError(`Unauthorized: Missing ${capability} for classroom`, 'FORBIDDEN');
  }

  return { userId, classroom };
}

/**
 * requireTeacherAccess  Ensures the user is a teacher (and optionally has school context).
 */
export async function requireTeacherAccess(schoolId?: string) {
  const userId = await requireAuth();
  const ability = composeUserAbilities({ userId, schoolId });

  if (!ability.can('read', 'TeacherProfile')) {
    throw new APIError('Unauthorized: Teacher access required', 'FORBIDDEN');
  }

  return userId;
}

/**
 * Cloudinary Integration Utility
 * Handles asset uploads to Cloudinary with auto-transcoding support via presets.
 */

export interface CloudinaryUploadResponse {
  secure_url: string;
  public_id: string;
  resource_type: string;
  format: string;
  width: number;
  height: number;
}

/**
 * Upload a file to Cloudinary
 * @param fileUri Local file URI from image picker or filesystem
 * @param resourceType 'image' | 'video' | 'auto'
 * @returns Promise<string> The secure URL of the uploaded asset
 */
export async function uploadToCloudinary(
  fileUri: string,
  resourceType: 'image' | 'video' | 'auto' = 'image',
): Promise<string> {
  const cloudName = process.env['EXPO_PUBLIC_CLOUDINARY_CLOUD_NAME'] || 'neevsk';
  const uploadPreset = process.env['EXPO_PUBLIC_CLOUDINARY_UPLOAD_PRESET'] || 'gurudevi_unsigned';

  if (!fileUri) {
    throw new Error('No file URI provided for upload');
  }

  const formData = new FormData();

  // Create the file object for FormData
  // In React Native/Expo, this is the standard way to handle file uploads via fetch
  const filename = fileUri.split('/').pop() || 'upload';
  const match = /\.(\w+)$/.exec(filename);
  const type = match ? `${resourceType}/${match[1]}` : resourceType;

  formData.append('file', {
    uri: fileUri,
    name: filename,
    type: type,
  } as any);

  formData.append('upload_preset', uploadPreset);

  try {
    const response = await fetch(
      `https://api.cloudinary.com/v1_1/${cloudName}/${resourceType}/upload`,
      {
        method: 'POST',
        body: formData,
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      },
    );

    if (!response.ok) {
      const errorData = await response.json();
      if (__DEV__) {
        console.error('\uD83D\uDCE6 Cloudinary Upload Error Details:', errorData);
      }
      throw new Error(errorData.error?.message || 'Cloudinary upload failed');
    }

    const data: CloudinaryUploadResponse = await response.json();
    if (__DEV__) {
      console.log(`\u2705 Asset uploaded successfully to Cloudinary: ${data.secure_url}`);
    }
    return data.secure_url;
  } catch (error) {
    if (__DEV__) {
      console.error('\uD83D\uDCE6 Cloudinary Upload Exception:', error);
    }
    throw error;
  }
}

/**
 * Sovereign Error Standard (2026 Edition)
 *
 * A structured error format that provides dual-resolution paths:
 * 1. Human Resolution: Empathetic, clear, and actionable for users.
 * 2. Agent Resolution: Technical, machine-readable, and precise for AI agents.
 */
export type ErrorResolutionAction = {
  label: string;
  onPress: () => void | Promise<void>;
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
};

export interface ISovereignError {
  id: string;
  timestamp: string;
  code: string;
  message: string;

  // Human-facing resolution logic
  guide: string; 

  // Agent-facing resolution logic (Operational precision)
  agentGuide?: string; 
  agentHint?: string; // Short code for agent decision trees (e.g. "RETRY_ON_CONNECT")

  context?: Record<string, any>;
  isRetriable?: boolean;
  actions?: ErrorResolutionAction[];
}

export class SovereignError extends Error implements ISovereignError {
  public readonly id: string;
  public readonly timestamp: string;
  public readonly code: string;
  public readonly guide: string;
  public readonly agentGuide?: string;
  public readonly agentHint?: string;
  public readonly context?: Record<string, any>;
  public readonly isRetriable?: boolean;
  public readonly actions?: ErrorResolutionAction[];

  constructor(options: {
    message: string;
    code: string;
    guide: string;
    agentGuide?: string;
    agentHint?: string;
    context?: Record<string, any>;
    isRetriable?: boolean;
    actions?: ErrorResolutionAction[];
  }) {
    super(options.message);
    this.name = 'SovereignError';
    this.id = Math.random().toString(36).substring(2, 15);
    this.timestamp = new Date().toISOString();
    this.code = options.code;
    this.guide = options.guide;
    this.agentGuide = options.agentGuide;
    this.agentHint = options.agentHint;
    this.context = options.context;
    this.isRetriable = options.isRetriable;
    this.actions = options.actions;

    Object.setPrototypeOf(this, SovereignError.prototype);
  }

  public static from(error: any, overrides?: Partial<ISovereignError>): SovereignError {
    if (error instanceof SovereignError) return error;

    return new SovereignError({
      message: error?.message || 'An unexpected error occurred',
      code: error?.code || 'UNKNOWN_ERROR',
      guide: 'Please try again or contact support if the issue persists.',
      agentGuide: 'Generic failure caught. Check transaction logs for root cause.',
      agentHint: 'LOG_AND_ESCALATE',
      context: { originalError: error },
      ...overrides,
    });
  }
}

