  return {
    ...snapshot,
    publication_state: snapshot.publication_state === 'published' ? 'published' : 'draft',
    published_at: snapshot.published_at ?? snapshot.publishedAt ?? null,
    published_by: snapshot.published_by ?? snapshot.publishedBy ?? null,
    publication_action: snapshot.publication_action ?? null,
  } as GradePublicationSnapshot;
}

export function annotateGradesWithPublicationState(
  grades: Grade[],
  rows: GradeLifecycleAuditRow[],
): GradePublicationSnapshot[] {
  const latestByGradeId = new Map<string, GradeLifecycleAuditRow>();

  rows.forEach((row) => {
    const gradeId = rowEntityId(row);
    if (!gradeId) return;

    const current = latestByGradeId.get(gradeId);
    if (!current || rowTimestamp(row) > rowTimestamp(current)) {
      latestByGradeId.set(gradeId, row);
    }
  });

  return grades.map((grade) => {
    const latest = latestByGradeId.get(grade.id);
    const metadata = latest?.metadata ?? {};
    const publicationState =
      metadata['publicationState'] === 'published' ||
      (latest?.action ? GRADE_PUBLISHED_ACTIONS.includes(latest.action as any) : false)
        ? 'published'
        : 'draft';

    return {
      ...grade,
      publication_state: publicationState,
      published_at: metadata['publishedAt'] ?? null,
      published_by: metadata['publishedBy'] ?? null,
      publication_action: latest?.action ?? null,
    };
  });
}

export function selectLatestPublishedSnapshots(
  rows: GradeLifecycleAuditRow[],
): GradePublicationSnapshot[] {
  const latestByGradeId = new Map<string, GradeLifecycleAuditRow>();

  rows.forEach((row) => {
    if (!row.action || !GRADE_PUBLISHED_ACTIONS.includes(row.action as any)) return;
    const gradeId = rowEntityId(row);
    if (!gradeId) return;

    const current = latestByGradeId.get(gradeId);
    if (!current || rowTimestamp(row) > rowTimestamp(current)) {
      latestByGradeId.set(gradeId, row);
    }
  });

  return Array.from(latestByGradeId.values())
    .map((row) => normalizeSnapshot(row.metadata?.['snapshot']))
    .filter((snapshot): snapshot is GradePublicationSnapshot => snapshot !== null)
    .sort((a, b) => (b.published_at?.getTime() ?? b.updated_at.getTime()) - (a.published_at?.getTime() ?? a.updated_at.getTime()));
}

/**
 * Sri Lankan Standard Grading Conversion
 *
 * A: 75-100 (4.0)
 * B: 65-74 (3.0)
 * C: 50-64 (2.0)
 * S: 35-49 (1.0)
 * F: 0-34 (0.0)
 */
export function marksToGPA(marks: number): { grade: string; gpa: number } {
  if (marks >= 75) return { grade: 'A', gpa: 4.0 };
  if (marks >= 65) return { grade: 'B', gpa: 3.0 };
  if (marks >= 50) return { grade: 'C', gpa: 2.0 };
  if (marks >= 35) return { grade: 'S', gpa: 1.0 };
  return { grade: 'F', gpa: 0.0 };
}
/**
 * Calculates ranks based on marks
 */
export interface GradeWithMarks {
  id: string;
  marks: number;
  [key: string]: any;
}

export interface GradeWithRank extends GradeWithMarks {
  rank: number;
}

export function calculateRanks(grades: GradeWithMarks[]): GradeWithRank[] {
  const sorted = [...grades].sort((a, b) => b.marks - a.marks);
  return grades.map((grade) => {
    const rank = sorted.findIndex((s) => s.id === grade.id) + 1;
    return { ...grade, rank };
  });
}

import { supabase } from '../api/supabase';

/**
 * Invite Code Validation and Management
 */

export interface InviteCodeData {
  id: string;
  school_id: string;
  code: string;
  role: 'teacher' | 'student' | 'principal';
  school_name?: string;
  school_type?: string;
  is_active: boolean;
  uses_count: number;
  max_uses: number | null;
}

/**
 * Validate invite code format
 * Format: GURU-ABC123-TEACH or GURU-ABC123-STUDY
 */
export function validateInviteCodeFormat(code: string): boolean {
  const pattern = /^GURU-[A-Z0-9]{6}-(TEACH|STUDY|ADMIN)$/;
  return pattern.test(code.toUpperCase());
}

/**
 * Check if invite code exists and is valid in database
 */
export async function validateInviteCode(code: string): Promise<{
  valid: boolean;
  data?: InviteCodeData;
  error?: string;
}> {
  try {
    // Validate format first
    if (!validateInviteCodeFormat(code)) {
      return {
        valid: false,
        error: 'Invalid code format. Expected: GURU-ABC123-TEACH',
      };
    }

    // Query database
    const { data, error } = await supabase
      .from('invite_codes')
      .select(`
        id,
        school_id,
        code,
        role,
        is_active,
        uses_count,
        max_uses,
        schools (
          name,
          type
        )
      `)
      .eq('code', code.toUpperCase())
      .eq('is_active', true)
      .single();

    if (error || !data) {
      return {
        valid: false,
        error: 'Invalid or expired invite code',
      };
    }

    // Check if code has reached max uses
    if (data.max_uses && data.uses_count >= data.max_uses) {
      return {
        valid: false,
        error: 'This invite code has reached its usage limit',
      };
    }

    return {
      valid: true,
      data: {
        ...data,
        school_name: (data.schools as any)?.name,
        school_type: (data.schools as any)?.type,
      },
    };
  } catch (error) {
    console.error('Error validating invite code:', error);
    return {
      valid: false,
      error: 'Failed to validate code. Please try again.',
    };
  }
}

/**
 * Increment invite code usage count
 */
export async function incrementInviteCodeUsage(code: string): Promise<void> {
  try {
    // Fetch current count
    const { data: currentData } = await supabase
      .from('invite_codes')
      .select('uses_count')
      .eq('code', code.toUpperCase())
      .single();

    if (currentData) {
      // Increment and update
      const { error } = await supabase
        .from('invite_codes')
        .update({ uses_count: currentData.uses_count + 1 })
        .eq('code', code.toUpperCase());

      if (error) {
        console.error('Error incrementing invite code usage:', error);
      }
    }
  } catch (error) {
    console.error('Error incrementing invite code usage:', error);
  }
}

/**
 * Generate invite codes for a school (called after principal creates school)
 */
export async function generateInviteCodesForSchool(
  schoolId: string,
  createdBy: string,
): Promise<{
  teacherCode?: string;
  studentCode?: string;
  error?: string;
}> {
  try {
    // Generate teacher code
    const teacherCode = generateInviteCode('teacher');
    const studentCode = generateInviteCode('student');

    const { error } = await supabase.from('invite_codes').insert([
      {
        school_id: schoolId,
        code: teacherCode,
        role: 'teacher',
        created_by: createdBy,
      },
      {
        school_id: schoolId,
        code: studentCode,
        role: 'student',
        created_by: createdBy,
      },
    ]);

    if (error) {
      console.error('Error creating invite codes:', error);
      return { error: 'Failed to generate invite codes' };
    }

    return { teacherCode, studentCode };
  } catch (error) {
    console.error('Error generating invite codes:', error);
    return { error: 'Failed to generate invite codes' };
  }
}

/**
 * Generate a random invite code (client-side)
 * Format: GURU-ABC123-TEACH
 */
function generateInviteCode(role: 'teacher' | 'student'): string {
  const suffix = role === 'teacher' ? 'TEACH' : 'STUDY';
  const randomPart = Math.random().toString(36).substring(2, 8).toUpperCase().padEnd(6, '0');
  return `GURU-${randomPart}-${suffix}`;
}

/**
 * Extract role from invite code
 */
export function getRoleFromCode(code: string): 'teacher' | 'student' | null {
  if (code.endsWith('-TEACH')) return 'teacher';
  if (code.endsWith('-STUDY')) return 'student';
  return null;
}

/**
 * PostHog Abstract Interface
 *
 * This file defines the generic interface for analytics.
 * Shells (Mobile, Web, Server) must inject their platform-specific
 * implementation into this singleton using injectPostHog().
 *
 * CORE PURITY: No platform-specific imports (React Native/Browser/Node) here.
 */

export interface IPostHog {
  identify(userId: string, properties?: Record<string, any>): void;
  capture(event: string, properties?: Record<string, any>): void;
  screen?(screenName: string, properties?: Record<string, any>): void;
  reset(): void;
  flush?(): Promise<void>;
}

let _posthog: IPostHog | null = null;

/**
 * Injection point for platform-specific PostHog instance.
 * Call this in the App Entry/Shell.
 */
export const injectPostHog = (instance: IPostHog) => {
  _posthog = instance;
};

export const isPostHogInitialized = () => _posthog !== null;

export const initPostHog = async () => {
  // Legacy function signature to maintain compatibility with existing hook calls.
  // Initialization should actually be handled by the shell.
  if (!_posthog && typeof __DEV__ !== 'undefined' && __DEV__) {
    console.warn(
      '[PostHog] initPostHog called but no instance injected. Ensure injectPostHog() is called in shell.',
    );
  }
};

export const trackEvent = (event: string, properties?: any) => {
  if (_posthog) {
    _posthog.capture(event, properties);
  } else if (typeof __DEV__ !== 'undefined' && __DEV__) {
    console.log('[PostHog Bridge] Event tracked (noop):', event, properties);
  }
};

export const identifyUser = (userId: string, properties?: any) => {
  if (_posthog) {
    _posthog.identify(userId, properties);
  } else if (typeof __DEV__ !== 'undefined' && __DEV__) {
    console.log('[PostHog Bridge] User identified (noop):', userId, properties);
  }
};

export const resetUser = () => {
  if (_posthog) {
    _posthog.reset();
  }
};

export const trackScreen = (screenName: string, properties?: any) => {
  if (_posthog?.screen) {
    _posthog.screen(screenName, properties);
  } else if (_posthog) {
    _posthog.capture('$screen_view', {
      screen_name: screenName,
      ...properties,
    });
  }
};

