import { cryptoManager } from '../logic/managers/CryptoManager';
import { getActiveAccountId, scopeStorageKey } from './accountScope';

const SUPABASE_URL = process.env['EXPO_PUBLIC_SUPABASE_URL'];

function getProjectRef() {
  if (!SUPABASE_URL) return 'default';

  try {
    const hostname = new URL(SUPABASE_URL).hostname;
    return hostname.split('.')[0]! || 'default';
  } catch {
    return 'default';
  }
}

const AUTH_TOKEN_STORAGE_KEY = `sb-${getProjectRef()}-auth-token`;

async function readStorage(key: string): Promise<string | null> {
  return cryptoManager.getItemAsync(key);
}

async function writeStorage(key: string, value: string): Promise<void> {
  await cryptoManager.setItemAsync(key, value);
}

async function deleteStorage(key: string): Promise<void> {
  await cryptoManager.deleteItemAsync(key);
}

function getScopedAuthStorageKey(accountId: string | null, key: string) {
  return scopeStorageKey(`auth:${key}`, accountId);
}

function normalizeStoredSession(parsed: unknown) {
  if (!parsed || typeof parsed !== 'object') return null;

  const direct = parsed as { access_token?: string; refresh_token?: string };
  if (direct.access_token && direct.refresh_token) {
    return direct;
  }

  const nested = parsed as {
    currentSession?: { access_token?: string; refresh_token?: string };
  };
  if (nested.currentSession?.access_token && nested.currentSession?.refresh_token) {
    return nested.currentSession;
  }

  return null;
}

export const supabaseAuthStorage = {
  async getItem(key: string) {
    const scopedKey = getScopedAuthStorageKey(getActiveAccountId(), key);
    const scopedValue = await readStorage(scopedKey);
    if (scopedValue != null) {
      return scopedValue;
    }

    return readStorage(key);
  },

  async setItem(key: string, value: string) {
    const scopedKey = getScopedAuthStorageKey(getActiveAccountId(), key);
    await writeStorage(scopedKey, value);
  },

  async removeItem(key: string) {
    const scopedKey = getScopedAuthStorageKey(getActiveAccountId(), key);
    await deleteStorage(scopedKey);
    await deleteStorage(key);
  },
};

export async function getStoredSessionForAccount(accountId: string | null) {
  const raw = await readStorage(getScopedAuthStorageKey(accountId, AUTH_TOKEN_STORAGE_KEY));
  if (!raw) return null;

  try {
    return normalizeStoredSession(JSON.parse(raw));
  } catch {
    return null;
  }
}

export async function setStoredSessionForAccount(
  accountId: string | null,
  session: { access_token: string; refresh_token: string },
) {
  await writeStorage(
    getScopedAuthStorageKey(accountId, AUTH_TOKEN_STORAGE_KEY),
    JSON.stringify(session),
  );
}

export async function removeStoredSessionForAccount(accountId: string | null) {
  await deleteStorage(getScopedAuthStorageKey(accountId, AUTH_TOKEN_STORAGE_KEY));
}

export async function clearLegacySupabaseSession() {
  await deleteStorage(AUTH_TOKEN_STORAGE_KEY);
}

import { create } from 'zustand';
import { createJSONStorage, persist } from 'zustand/middleware';
import { SafeZustandStorage } from '../../lib/storageWrapper';

import type { MutationOutcome } from './types';

export interface AuditEntry {
  id: string; // Same UUID as QueuedMutation.id
  idempotencyKey: string;
  scope: string;
  name: string;
  status: MutationOutcome;
  attempts: number;
  queuedAt: number; // Unix ms
  updatedAt: number; // Last status change
  syncedAt?: number;
  lastError?: string;
}

interface MutationAuditLogState {
  entries: AuditEntry[];
  logEntry: (entry: Omit<AuditEntry, 'updatedAt'>) => void;
  updateEntry: (id: string, status: MutationOutcome, error?: string) => void;
  clearLog: () => void;
}

const MAX_ENTRIES = 200;

/**
 * useMutationAuditLog
 *
 * Persistent "Temporal Memory" of all mutations.
 * Implements a ring-buffer to keep the last 200 entries.
 */
export const useMutationAuditLog = create<MutationAuditLogState>()(
  persist(
    (set, _get) => ({
      entries: [],

      logEntry: (entry) => {
        const newEntry: AuditEntry = {
          ...entry,
          updatedAt: Date.now(),
        };

        set((state) => {
          const newEntries = [newEntry, ...state.entries];
          return {
            entries: newEntries.slice(0, MAX_ENTRIES),
          };
        });
      },

      updateEntry: (id, status, error) => {
        set((state) => ({
          entries: state.entries.map((e) =>
            e.id === id
              ? {
                  ...e,
                  status,
                  lastError: error || e.lastError,
                  updatedAt: Date.now(),
                  syncedAt: status === 'success' ? Date.now() : e.syncedAt,
                  attempts: status === 'retrying' ? e.attempts + 1 : e.attempts,
                }
              : e,
          ),
        }));
      },

      clearLog: () => {
        set({ entries: [] });
      },
    }),
    {
      name: 'gurudevi-mutation-audit-log',
      storage: createJSONStorage(() => SafeZustandStorage),
    },
  ),
);

// @ts-ignore - fast-json-patch is installed but tsc environment may need refresh
import { compare, applyPatch, Operation } from 'fast-json-patch';

/**
 * DeltaResonance Utility
 * 
 * Provides surgical state diffing and patching for low-bandwidth sync.
 * Aligned with 2026 "Server-First" and "Resilience-First" standards.
 */
export const DeltaResonance = {
  /**
   * Generates a JSON Patch (delta) between two states.
   */
  diff: <T>(original: T, updated: T): Operation[] => {
    return compare(original as any, updated as any);
  },

  /**
   * Applies a JSON Patch to a state.
   */
  patch: <T>(original: T, patch: Operation[]): T => {
    const result = applyPatch(original as any, patch);
    return result.newDocument as T;
  },

  /**
   * Optimizes a mutation payload by converting it to a delta if possible.
   * This is used in useSafeMutation to reduce queue size.
   */
  createDeltaMutation: <T>(baseState: T, newState: T, name: string) => {
    const patch = DeltaResonance.diff(baseState, newState);
    return {
      name,
      type: 'DELTA' as const,
      patch,
      timestamp: Date.now(),
    };
  }
};

