export default function SyncManager({ dispatchQueuedMutation }: SyncManagerProps = {}) {
  const isOnline = useStore((state) => state.isOnline);
  const { queue, removeFromQueue, updateMutation, moveToDeadLetter, setSyncing, isSyncing } =
    useMutationQueue();
  const { updateEntry } = useMutationAuditLog();
  const { addConflict, activeConflicts } = useConflictStore();
  const showToast = useStore((state) => state.showToast);

  const MAX_RETRIES = 5; // Increased for better robustness

  const processQueue = useCallback(async () => {
    setSyncing(true);
    if (__DEV__) {
      console.log(`[ResonantSync] Analyzing outbox: ${queue.length} items pending.`);
    }

    const currentQueue = [...queue];
    let processedCount = 0;

    for (const item of currentQueue) {
      // Respect Conflict Locking: Don't retry if a conflict is already active for this mutation
      if (activeConflicts.some(c => c.id === item.id)) {
        continue;
      }

      // Respect Temporal Pacing (Backoff)
      if (item.backoffUntil && Date.now() < item.backoffUntil) {
        continue;
      }

      try {
        const mutationFn = MUTATION_REGISTRY[item.name];

        if (!mutationFn) {
          console.warn(`[SyncManager] Unknown mutation: ${item.name}. Moving to DLQ.`);
          moveToDeadLetter(item.id, 'UNKNOWN_MUTATION');
          updateEntry(item.id, 'dead_letter', 'Unknown mutation registry key');
          continue;
        }

        if (dispatchQueuedMutation) {
          const dispatchResult = await dispatchQueuedMutation(item);
          if (dispatchResult === 'dispatched') {
            removeFromQueue(item.id);
            updateEntry(item.id, 'dispatched');
            processedCount++;
            continue;
          }
        }

        updateEntry(item.id, 'syncing');
        await mutationFn(item.variables);

        // Success! (Resonance achieved)
        removeFromQueue(item.id);
        updateEntry(item.id, 'success');
        processedCount++;
      } catch (error: any) {
        const errorType = classifyError(error);
        const retryCount = (item.retryCount || 0) + 1;

        if (errorType === 'PERMANENT' || retryCount >= MAX_RETRIES) {
          // Terminal State: Permanent Failure or Max Retries
          const exitReason =
            errorType === 'PERMANENT' ? 'PERMANENT_FAILURE' : 'MAX_RETRIES_EXCEEDED';
          if (__DEV__) {
            console.error(`[SyncManager] Terminal: ${item.name}  reason=${exitReason}`, error);
          }

          moveToDeadLetter(item.id, error.message);
          updateEntry(item.id, 'dead_letter', error.message);

          showToast(`Action required: ${item.name} failed permanentely`, 'error');
        } else if (errorType === 'CONFLICT') {
          // Resonance Fork: Data Conflict detected
          addConflict({
            id: item.id,
            scope: item.scope,
            name: item.name,
            localData: item.variables,
            remoteData: error.remoteState || null, // Capture remote state if provided by API
            timestamp: Date.now(),
          });

          showToast(`Conflict detected in ${item.name}`, 'info');
          updateEntry(item.id, 'terminal_abort', 'Data Conflict Detected');
        } else {
          // Transient failure - retry with exponential backoff
          const backoffMs = Math.min(2 ** retryCount * 1000, 30000);
          const backoffUntil = Date.now() + backoffMs;

          if (__DEV__) {
            console.log(`[SyncManager] Backoff: ${item.name} retrying in ${backoffMs}ms`);
          }
          updateMutation(item.id, {
            retryCount,
            backoffUntil,
            lastError: error.message,
          });
          updateEntry(item.id, 'retrying', error.message);
        }
      }
    }

    setSyncing(false);

    if (processedCount > 0) {
      showToast(`Synced ${processedCount} pending actions`, 'success');
    }
  }, [
    queue,
    removeFromQueue,
    updateMutation,
    moveToDeadLetter,
    setSyncing,
    dispatchQueuedMutation,
    updateEntry,
    showToast,
  ]);

  useEffect(() => {
    if (isOnline && queue.length > 0 && !isSyncing) {
      processQueue();
    }
  }, [isOnline, queue.length, isSyncing, processQueue]);

  return null;
}

/**
 * Persistence Types for Offline Synchronization
 */

export type MutationType = 'CREATE' | 'UPDATE' | 'DELETE' | 'CUSTOM' | 'PATCH';

export interface QueuedMutation {
  id: string;
  idempotencyKey: string; // Deterministic hash to prevent duplicate writes
  type: MutationType;
  scope: string; // e.g., 'community', 'classroom', 'self'
  name: string; // e.g., 'createPost', 'updateAttendance'
  variables: any;
  timestamp: number;
  retryCount: number;
  backoffUntil?: number; // Epoch ms - skip until this time
  lastError?: string; // Store the last error for the DLQ/Audit log
  userId?: string; // Attribution for conflict resolution
}

export type QueuedMutationDispatchResult = false | 'dispatched';

export interface MutationQueueState {
  queue: QueuedMutation[];
  deadLetterQueue: QueuedMutation[]; // Permanent failures
  isSyncing: boolean;
  addToQueue: (
    mutation: Omit<QueuedMutation, 'id' | 'timestamp' | 'retryCount' | 'idempotencyKey'>,
  ) => void;
  removeFromQueue: (id: string) => void;
  moveToDeadLetter: (id: string, reason: string) => void;
  updateMutation: (id: string, updates: Partial<QueuedMutation>) => void;
  clearQueue: () => void;
  clearDeadLetterQueue: () => void;
  setSyncing: (isSyncing: boolean) => void;
}

export type MutationOutcome =
  | 'success'
  | 'dispatched'
  | 'transient_failure'
  | 'permanent_failure'
  | 'terminal_abort'
  | 'queued'
  | 'syncing'
  | 'retrying'
  | 'dead_letter'
  | 'discarded';

export interface MutationResult {
  outcome: MutationOutcome;
  error?: string;
  retryCount: number;
  timestamp: number;
}

import { create } from 'zustand';
import { createJSONStorage, persist } from 'zustand/middleware';
import { SafeZustandStorage } from '../../lib/storageWrapper';
import { generateIdempotencyKey } from './idempotency';
import type { MutationQueueState, QueuedMutation } from './types';
import { v7 as uuidv7 } from 'uuid';

/**
 * useMutationQueue
 *
 * The Persistent "Outbox".
 * Stores actions that happened while offline so they can be replayed later.
 * Upgraded with Idempotency Dedup and Dead Letter Queue.
 */
export const useMutationQueue = create<MutationQueueState>()(
  persist(
    (set, get) => ({
      queue: [],
      deadLetterQueue: [],
      isSyncing: false,

      addToQueue: async (mutation) => {
        const idempotencyKey = await generateIdempotencyKey(
          mutation.scope,
          mutation.name,
          mutation.variables,
        );

        // Dedup: If mutation with same idempotency key is already in queue, skip
        const isDuplicate = get().queue.some((m) => m.idempotencyKey === idempotencyKey);
        if (isDuplicate) {
          if (__DEV__) {
            console.log(`[MutationQueue] Skipping duplicate intent: ${mutation.name}`);
          }
          return;
        }

        const newMutation: QueuedMutation = {
          ...mutation,
          id: uuidv7(),
          idempotencyKey,
          timestamp: Date.now(),
          retryCount: 0,
        };

        set((state) => ({
          queue: [...state.queue, newMutation],
        }));
      },

      removeFromQueue: (id) => {
        set((state) => ({
          queue: state.queue.filter((m) => m.id !== id),
        }));
      },

      moveToDeadLetter: (id, reason) => {
        const item = get().queue.find((m) => m.id === id);
        if (item) {
          set((state) => ({
            queue: state.queue.filter((m) => m.id !== id),
            deadLetterQueue: [...state.deadLetterQueue, { ...item, lastError: reason }],
          }));
        }
      },

      updateMutation: (id, updates) => {
        set((state) => ({
          queue: state.queue.map((m) => (m.id === id ? { ...m, ...updates } : m)),
        }));
      },

      clearQueue: () => {
        set({ queue: [] });
      },

      clearDeadLetterQueue: () => {
        set({ deadLetterQueue: [] });
      },

      setSyncing: (isSyncing) => {
        set({ isSyncing });
      },
    }),
    {
      name: 'gurudevi-mutation-queue',
      storage: createJSONStorage(() => SafeZustandStorage),
    },
  ),
);

import { useStore } from '../store/useStore';

/**
 * Global API Interceptor & Error Handler (Layer 1)
 * Wraps promise-based calls to provide consistent error reporting and user feedback.
 */

export interface SanctuaryAPIError {
  message: string;
  code?: string;
  status?: number;
}

/**
 * Maps technical error codes/messages to teacher-friendly Sanctuary messages.
 */
function mapErrorToMessage(error: any): string {
  const message = error?.message || '';
  const code = error?.code || '';

  // Network Errors
  if (message.includes('Network request failed') || message.includes('fetch')) {
    return 'The connection to the Sanctuary was lost. Please check your internet.';
  }

  // Auth Errors
  if (code === 'PGRST116' || message.includes('JWT')) {
    return 'Your session has reached a peaceful end. Please sign in again.';
  }
  if (message.includes('Invalid login credentials')) {
    return "Those credentials don't seem to match our scrolls. Please try again.";
  }

  // PostgREST / Database Errors
  if (code === '23505') return 'This record already exists in our archives.';
  if (code === '23503') return 'This action is restricted by existing relations.';
  if (code === '42P01') return "We couldn't find the requested section in our database.";
  if (code === '42501') return "Huh! You are a newbie aren't you?";

  // Environment / Bootstrap Errors
  if (message.includes('HMRClient')) {
    return ''; // Silence these environment-level bootstrap errors
  }

  // Default Fallback
  if (message.length > 0 && !message.includes('PostgreSQL')) {
    return message; // Keep custom messages if they aren't robotic DB notes
  }

  return 'A peaceful moment was interrupted. Please try again.';
}

/**
 * Handles errors from Supabase or other API calls
 * Logs to console (and Sentry in production) and shows a friendly toast.
 */
export function handleAPIError(error: any, silent = false) {
  const apiError: SanctuaryAPIError = {
    message: mapErrorToMessage(error),
    code: error?.code,
    status: error?.status,
  };

  if (__DEV__) {
    console.error('\uD83D\uDED1 API Error Intercepted:', error); // Log original for debugging
    console.log('\u2728 Friendly Message:', apiError.message);
  }

  // TODO: Track with Sentry
  // Sentry.captureException(error);

  if (!silent && apiError.message) {
    useStore.getState().showToast(apiError.message, 'error');
  }

  return apiError;
}

/**
 * Wrapper for async operations to provide automatic error handling
 */
export async function withErrorHandling<T>(
  promise: Promise<T>,
  options: { silent?: boolean; toastMessage?: string } = {},
): Promise<T | null> {
  try {
    return await promise;
  } catch (error) {
    handleAPIError(error, options.silent);
    return null;
  }
}

