import type React from 'react';
import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';

interface ActivityPulseState {
  pulse: number; // 0 to 1, representing recent activity intensity
  lastEventTime: number;
  intensity: number; // Cumulative intensity
}

interface ActivityPulseContextType {
  state: ActivityPulseState;
  registerPulse: (strength?: number) => void;
}

const ActivityPulseContext = createContext<ActivityPulseContextType | undefined>(undefined);

export const ActivityPulseProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [state, setState] = useState<ActivityPulseState>({
    pulse: 0,
    lastEventTime: Date.now(),
    intensity: 0,
  });

  const decayRef = useRef<number | null>(null);

  const registerPulse = useCallback((strength: number = 0.2) => {
    setState((prev) => ({
      ...prev,
      pulse: Math.min(1, prev.pulse + strength),
      lastEventTime: Date.now(),
      intensity: prev.intensity + strength,
    }));
  }, []);

  useEffect(() => {
    // Decay function to make the pulse fade over time
    const decay = () => {
      setState((prev) => {
        if (prev.pulse <= 0.01) return prev;
        return {
          ...prev,
          pulse: prev.pulse * 0.95, // 5% decay per frame-ish
        };
      });
      decayRef.current = requestAnimationFrame(decay);
    };

    decayRef.current = requestAnimationFrame(decay);
    return () => {
      if (decayRef.current) cancelAnimationFrame(decayRef.current);
    };
  }, []);

  const value = useMemo(() => ({ state, registerPulse }), [state, registerPulse]);

  return (
    <ActivityPulseContext.Provider value={value}>
      {children}
    </ActivityPulseContext.Provider>
  );
};

export const useActivityPulse = () => {
  const context = useContext(ActivityPulseContext);
  if (!context) {
    throw new Error('useActivityPulse must be used within an ActivityPulseProvider');
  }
  return context;
};

import type { FieldDefinition, FormResponse } from '../../types';

export interface FieldAnalytics {
  fieldId: string;
  label: string;
  type: string;
  totalResponses: number;
  data: any; // Frequency counts, averages, or raw list
}

export const formAnalytics = {
  /**
   * Aggregates raw responses into structured analytical data
   */
  aggregate(fields: FieldDefinition[], responses: FormResponse[]): FieldAnalytics[] {
    return fields.map((field) => {
      const fieldLabel = field.label ?? field.name ?? field.id;
      const values = responses
        .map((r) => r.data[field.name])
        .filter((v) => v !== undefined && v !== null);

      let aggregatedData: any = null;

      if (field.type === 'select') {
        const initialCounts: Record<string, number> = {};
        field.options?.forEach((opt) => {
          initialCounts[opt.value] = 0;
        });

        aggregatedData = values.reduce((acc: any, val: any) => {
          acc[val] = (acc[val] || 0) + 1;
          return acc;
        }, initialCounts);
      } else if (field.type === 'number') {
        const numericValues = values.map(Number).filter((v) => !Number.isNaN(v));
        const sum = numericValues.reduce((a, b) => a + b, 0);
        aggregatedData = {
          average: numericValues.length > 0 ? sum / numericValues.length : 0,
          min: Math.min(...numericValues),
          max: Math.max(...numericValues),
          count: numericValues.length,
        };
      } else {
        // For text/email etc, just return the last 10 unique entries
        aggregatedData = Array.from(new Set(values)).slice(-10);
      }

      return {
        fieldId: field.id,
        label: fieldLabel,
        type: field.type,
        totalResponses: values.length,
        data: aggregatedData,
      };
    });
  },

  /**
   * Converts form responses to a CSV string
   */
  toCSV(fields: FieldDefinition[], responses: FormResponse[]): string {
    if (responses.length === 0) return '';

    const headers = ['Submitted At', ...fields.map((f) => f.label ?? f.name ?? f.id)];
    const rows = responses.map((r) => {
      const row = [
        new Date(r.submitted_at).toLocaleString(),
        ...fields.map((f) => {
          const val = r.data[f.name];
          // Handle commas and quotes for CSV safety
          if (typeof val === 'string' && (val.includes(',') || val.includes('"'))) {
            return `"${val.replace(/"/g, '""')}"`;
          }
          return val ?? '';
        }),
      ];
      return row.join(',');
    });

    return [headers.join(','), ...rows].join('\n');
  },
  /**
   * Converts form responses to an Excel-compatible XML (SpreadsheetML) string
   */
  toXLSX(fields: FieldDefinition[], responses: FormResponse[]): string {
    const headers = ['Submitted At', ...fields.map((f) => f.label ?? f.name ?? f.id)];
    const rows = responses.map((r) => {
      return [
        new Date(r.submitted_at).toLocaleString(),
        ...fields.map((f) => r.data[f.name] ?? ''),
      ];
    });

    const xmlHeader = `<?xml version="1.0"?><?mso-application progid="Excel.Sheet"?
<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:o="urn:schemas-microsoft-com:office:office"
 xmlns:x="urn:schemas-microsoft-com:office:excel"
 xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:html="http://www.w3.org/TR/REC-html40"
 <Worksheet ss:Name="Form Responses"
  <Table>`;

    const xmlFooter = `  </Table
 </Worksheet
</Workbook>`;

    const headerRow = `   <Row ss:StyleID="Header"
${headers.map((h) => `    <Cell><Data ss:Type="String">${h}</Data></Cell>`).join('\n')}
   </Row>`;

    const dataRows = rows
      .map((row) => {
        return `   <Row
${row.map((val) => `    <Cell><Data ss:Type="${typeof val === 'number' ? 'Number' : 'String'}">${val}</Data></Cell>`).join('\n')}
   </Row>`;
      })
      .join('\n');

    return `${xmlHeader}\n${headerRow}\n${dataRows}\n${xmlFooter}`;
  },

  /**
   * Generates a QR Code URL for a given form slug
   */
  getQRCodeURL(slug: string): string {
    const publicURL = `${window.location.origin}/form/${slug}`;
    return `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(publicURL)}&bgcolor=FFFFFF&color=333333&qzone=2&margin=0`;
  },
};

﻿import { validators } from '../utils/validators';
import type { FormConfig } from './form-manager';
import { FormManager } from './form-manager';

/**
 * Hydrates a FormManager from a JSON configuration.
 * This is useful for loading forms created by users (Google Forms style).
 */
export class FormHydrator {
  /**
   * Creates a FormManager from a raw JSON object.
   * This handles mapping string validator names to actual functions.
   */
  static hydrate<T extends Record<string, any>>(
    json: any,
    onSubmit: (values: T) => Promise<void>,
  ): FormManager<T> {
    const fields: any = {};
    json.fields.forEach((field: any) => {
      fields[field.name] = {
        ...field,
        validators: field.validate ? [FormHydrator.mapValidator(field.validate)] : undefined,
      };
    });

    const config: FormConfig<T> = {
      fields,
      onSubmit,
    };

    return new FormManager<T>(config);
  }

  private static mapValidator(validatorName: string): (val: any) => string | undefined {
    // Map common validator names to the actual functions in @repo/core
    const validatorMap: Record<string, any> = {
      email: validators.email,
      nonEmpty: (val: any) => validators.nonEmpty(val, 'Field'),
      number: (val: any) => ({
        isValid: !Number.isNaN(Number(val)),
        error: Number.isNaN(Number(val)) ? 'Must be a number' : undefined,
      }),
    };

    return validatorMap[validatorName] || ((_: any) => undefined);
  }
}

import type { FormConfig } from '../../types';

export type { FormConfig };

export type FormState<T extends Record<string, any>> = {
  values: T;
  errors: Partial<Record<keyof T, string>>;
  isSubmitting: boolean;
  isDirty: boolean;
  isValid: boolean;
  submitError: string | null;
  submitSuccess: boolean;
};

export class FormManager<T extends Record<string, any>> {
  private state: FormState<T>;
  private subscribers: Set<(state: FormState<T>) => void> = new Set();
  public config: FormConfig<T>;

  constructor(config: FormConfig<T>) {
    this.config = config;

    const initialValues = {} as T;
    for (const key in config.fields) {
      (initialValues as Record<string, any>)[key] = config.fields[key].defaultValue ?? '';
    }

    this.state = {
      values: initialValues,
      errors: {},
      isSubmitting: false,
      isDirty: false,
      isValid: true,
      submitError: null,
      submitSuccess: false,
    };
  }

  public getState(): FormState<T> {
    return { ...this.state };
  }

  public getConfig(): FormConfig<T> {
    return this.config;
  }

  public subscribe(callback: (state: FormState<T>) => void): () => void {
    this.subscribers.add(callback);
    callback(this.state);
    return () => this.subscribers.delete(callback);
  }

  private notify() {
    this.subscribers.forEach((cb) => {
      cb(this.state);
    });
  }

  public setFieldValue<K extends keyof T>(field: K, value: T[K]) {
    this.state.values[field] = value;
    this.state.isDirty = true;
    this.validateField(field);
    this.notify();
  }

  public validateField(field: keyof T): boolean {
    const fieldConfig = this.config.fields[field];
    const value = this.state.values[field];

    // 1. Check required
