import { useTemporalStore } from '../../store/useTemporalStore';
import { applyTemporalFilter, getTemporalRange } from './temporalUtils';

describe('temporalUtils', () => {
  afterEach(() => {
    useTemporalStore.getState().resetToToday();
    useTemporalStore.setState({ viewScale: 'day' });
  });

  test('getTemporalRange returns a bounded day range', () => {
    const range = getTemporalRange('2026-03-27', 'day');

    expect(range.start).toContain('2026-03-27T00:00:00');
    expect(range.end).toContain('2026-03-27T23:59:59');
  });

  test('applyTemporalFilter uses requested column and event-time bounds', () => {
    const calls: Array<[string, string]> = [];
    const query = {
      gte: vi.fn((column: string, value: string) => {
        calls.push(['gte', `${column}:${value}`]);
        return query;
      }),
      lte: vi.fn((column: string, value: string) => {
        calls.push(['lte', `${column}:${value}`]);
        return query;
      }),
    } as any;

    useTemporalStore.setState({
      viewDate: '2026-03-27',
      phase: 'past',
      viewScale: 'week',
    });

    applyTemporalFilter(query, {
      column: 'created_at',
      mode: 'event_time',
      capability: 'event_stream',
    });

    expect(calls[0]?.[1]).toContain('created_at:2026-03');
    expect(calls[1]?.[1]).toContain('created_at:2026-03');
  });

  test('applyTemporalFilter uses business-date semantics for date facts', () => {
    const calls: Array<[string, string]> = [];
    const query = {
      gte: vi.fn((column: string, value: string) => {
        calls.push(['gte', `${column}:${value}`]);
        return query;
      }),
      lte: vi.fn((column: string, value: string) => {
        calls.push(['lte', `${column}:${value}`]);
        return query;
      }),
    } as any;

    useTemporalStore.setState({
      viewDate: '2026-03-27',
      phase: 'past',
      viewScale: 'month',
    });

    applyTemporalFilter(query, {
      column: 'date',
      mode: 'business_date',
      capability: 'business_fact',
    });

    expect(calls[0]?.[1]).toBe('date:2026-03-01');
    expect(calls[1]?.[1]).toBe('date:2026-03-31');
  });

  test('present snapshot queries are left untouched', () => {
    const query = {
      gte: vi.fn(),
      lte: vi.fn(),
    } as any;

    useTemporalStore.setState({
      viewDate: '2026-03-27',
      phase: 'present',
      viewScale: 'day',
    });

    const result = applyTemporalFilter(query, {
      column: 'created_at',
      mode: 'event_time',
      capability: 'snapshot',
    });

    expect(result).toBe(query);
    expect(query.gte).not.toHaveBeenCalled();
    expect(query.lte).not.toHaveBeenCalled();
  });
});

import type { PostgrestFilterBuilder } from '@supabase/postgrest-js';
import {
  endOfDay,
  endOfMonth,
  endOfWeek,
  endOfYear,
  formatISO,
  parseISO,
  startOfDay,
  startOfMonth,
  startOfWeek,
  startOfYear,
} from 'date-fns';
import {
  type TemporalCapability,
  type TemporalScale,
  useTemporalStore,
} from '../../store/useTemporalStore';

export interface TemporalRange {
  start: string; // ISO string
  end: string; // ISO string
}

export interface TemporalFilterSpec {
  column: string;
  mode: 'event_time' | 'business_date';
  scale?: TemporalScale;
  capability?: TemporalCapability;
}

/**
 * Generates ISO strings for a specific temporal scale.
 */

export const getTemporalRange = (dateStr: string, scale: TemporalScale = 'day'): TemporalRange => {
  const date = parseISO(dateStr);

  let start: Date;
  let end: Date;

  switch (scale) {
    case 'week':
      start = startOfWeek(date);
      end = endOfWeek(date);
      break;
    case 'month':
      start = startOfMonth(date);
      end = endOfMonth(date);
      break;
    case 'year':
      start = startOfYear(date);
      end = endOfYear(date);
      break;
    default:
      start = startOfDay(date);
      end = endOfDay(date);
      break;
  }

  return {
    start: formatISO(start),
    end: formatISO(end),
  };
};

/**
 * Higher-order utility to apply temporal filtering to a query builder.
 *
 * Important guardrail: timestamps alone are not equivalent to historical truth.
 * Only event streams, business facts, and audit histories should be filtered here.
 */
export function applyTemporalFilter<_Schema = any, _Table = any, _Result = any>(
  query: PostgrestFilterBuilder<any, any, any, any, any>,
  spec: TemporalFilterSpec,
) {
  const { viewDate, phase, viewScale } = useTemporalStore.getState();

  if (phase === 'present' && spec.capability === 'snapshot') {
    return query;
  }

  if (
    spec.capability &&
    !['event_stream', 'business_fact', 'audit_history'].includes(spec.capability)
  ) {
    return query;
  }

  const scale = spec.scale ?? viewScale;
  const { start, end } = getTemporalRange(viewDate, scale === 'custom' ? 'day' : scale);

  if (spec.mode === 'business_date') {
    const startDate = start.split('T')[0] || start;
    const endDate = end.split('T')[0] || end;
    return query.gte(spec.column, startDate).lte(spec.column, endDate);
  }

  return query.gte(spec.column, start).lte(spec.column, end);
}

/**
 * Bi-temporal utility: Returns a range for Transaction Time analysis.
 */
export const getTransactionRange = (validDate: string): TemporalRange => {
  // In a true bi-temporal system, we might look for the state recorded
  // nearest to the valid date. For now, we align with Valid Time.
  return getTemporalRange(validDate);
};

export const getCurrentTimestamp = () => {
	return formatISO(new Date());
};

﻿/**
 * INPUT VALIDATION UTILITIES
 *
 * Comprehensive validation functions for form inputs.
 * Prevents invalid data from reaching the API and provides user-friendly error messages.
 */

export interface ValidationResult {
  isValid: boolean;
  error?: string;
}

export const validators = {
  /**
   * Validates email format
   */
  email: (email: string): ValidationResult => {
    const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email || email.trim().length === 0) {
      return { isValid: false, error: 'Email is required' };
    }
    if (!regex.test(email)) {
      return { isValid: false, error: 'Invalid email format' };
    }
    return { isValid: true };
  },

  /**
   * Validates password strength
   * Requirements: min 8 chars, uppercase, lowercase, number
   */
  password: (password: string): ValidationResult => {
    if (!password) {
      return { isValid: false, error: 'Password is required' };
    }
    if (password.length < 8) {
      return {
        isValid: false,
        error: 'Password must be at least 8 characters',
      };
    }
    if (!/[A-Z]/.test(password)) {
      return {
        isValid: false,
        error: 'Password must contain an uppercase letter',
      };
    }
    if (!/[a-z]/.test(password)) {
      return {
        isValid: false,
        error: 'Password must contain a lowercase letter',
      };
    }
    if (!/[0-9]/.test(password)) {
      return { isValid: false, error: 'Password must contain a number' };
    }
    return { isValid: true };
  },

  /**
   * Validates non-empty string
   */
  nonEmpty: (value: string, fieldName: string = 'Field'): ValidationResult => {
    if (!value || value.trim().length === 0) {
      return { isValid: false, error: `${fieldName} is required` };
    }
    return { isValid: true };
  },

  /**
   * Validates maximum length
   */
  maxLength: (value: string, max: number, fieldName: string = 'Field'): ValidationResult => {
    if (value.length > max) {
      return {
        isValid: false,
        error: `${fieldName} must be less than ${max} characters`,
      };
    }
    return { isValid: true };
  },

  /**
   * Validates minimum length
   */
  minLength: (value: string, min: number, fieldName: string = 'Field'): ValidationResult => {
    if (value.length < min) {
      return {
        isValid: false,
        error: `${fieldName} must be at least ${min} characters`,
      };
    }
    return { isValid: true };
  },

  /**
   * Validates numeric range
   */
  numberRange: (
    value: number,
    min: number,
    max: number,
    fieldName: string = 'Value',
  ): ValidationResult => {
    if (Number.isNaN(value)) {
      return { isValid: false, error: `${fieldName} must be a number` };
    }
    if (value < min || value > max) {
      return {
        isValid: false,
        error: `${fieldName} must be between ${min} and ${max}`,
      };
    }
    return { isValid: true };
  },

  /**
   * Validates date format
   */
  date: (dateString: string): ValidationResult => {
    const date = new Date(dateString);
    if (Number.isNaN(date.getTime())) {
      return { isValid: false, error: 'Invalid date format' };
    }
    return { isValid: true };
  },

  /**
   * Validates mood score (1-5)
   */
  mood: (score: number): ValidationResult => {
    return validators.numberRange(score, 1, 5, 'Mood score');
  },

  /**
   * Validates grade level (1-13 for Sri Lankan system)
   */
  gradeLevel: (grade: number): ValidationResult => {
    return validators.numberRange(grade, 1, 13, 'Grade level');
  },

  /**
   * Validates marks (0-100)
   */
  marks: (marks: number): ValidationResult => {
    return validators.numberRange(marks, 0, 100, 'Marks');
  },

  /**
   * Validates phone number (Sri Lankan format)
   */
  phoneNumber: (phone: string): ValidationResult => {
    const regex = /^(\+94[0-9]{9}|0[0-9]{9})$/;
    if (!phone || phone.trim().length === 0) {
      return { isValid: false, error: 'Phone number is required' };
    }
    const cleanPhone = phone.replace(/\s/g, '');
    if (!regex.test(cleanPhone)) {
      return {
        isValid: false,
        error: 'Invalid phone number format. Use +94XXXXXXXXX or 0XXXXXXXXX',
      };
    }
    return { isValid: true };
  },

  /**
   * Validates URL format
   */
  url: (url: string): ValidationResult => {
    try {
      new URL(url);
      return { isValid: true };
    } catch {
      return { isValid: false, error: 'Invalid URL format' };
    }
  },
};

/**
 * Validates multiple form fields at once
 */
export function validateForm<T extends Record<string, any>>(
  values: T,
  rules: Partial<Record<keyof T, (value: any) => ValidationResult>>,
): { isValid: boolean; errors: Partial<Record<keyof T, string>> } {
  const errors: Partial<Record<keyof T, string>> = {};
  let isValid = true;

  for (const [field, validator] of Object.entries(rules)) {
    if (validator) {
      const result = validator(values[field]);
      if (!result.isValid) {
        errors[field as keyof T] = result.error;
        isValid = false;
      }
    }
  }

  return { isValid, errors };
}

/**
 * Validates a single field with multiple validators
 */
export function validateWithRules<T>(
  value: T,
  validators: Array<(value: T) => ValidationResult>,
): ValidationResult {
  for (const validator of validators) {
    const result = validator(value);
    if (!result.isValid) {
      return result;
    }
  }
  return { isValid: true };
}

