import Constants, { ExecutionEnvironment } from 'expo-constants';
import { Platform } from 'react-native';
// Adapters
import { AsyncStorageAdapter } from '../adapters/native/AsyncStorageAdapter';
import { MMKVStorageAdapter } from '../adapters/native/MMKVStorageAdapter';
import { NativeCryptoAdapter } from '../adapters/native/NativeCryptoAdapter';
import { NativeNetworkAdapter } from '../adapters/native/NativeNetworkAdapter';
import { SentryTelemetryAdapter } from '../adapters/native/SentryTelemetryAdapter';
import { WebNetworkAdapter } from '../adapters/WebNetworkAdapter';
import { cryptoManager } from '../logic/managers/CryptoManager';
import { networkManager } from '../logic/managers/NetworkManager';
// Managers
import { storage } from '../logic/managers/StorageManager';
import { telemetry } from '../logic/managers/TelemetryManager';

import { Runtime } from './runtime';

/**
 * Sovereign Bootstrap
 * Initializes all platform-specific adapters.
 */
export async function bootstrapPlatform() {
  const isExpoGo = Constants.executionEnvironment === ExecutionEnvironment.StoreClient;
  const isWeb = Platform.OS === 'web';
  const isReady = Runtime.isReady();

  // 1. Initialize Crypto & Telemetry (Unified)
  if (!isWeb) {
    cryptoManager.registerAdapter(new NativeCryptoAdapter());
    telemetry.registerAdapter(new SentryTelemetryAdapter());
    networkManager.registerAdapter(new NativeNetworkAdapter());
  } else {
    networkManager.registerAdapter(new WebNetworkAdapter());
  }

  // 2. Initialize Storage
  if (isExpoGo || isWeb || !isReady) {
    storage.registerAdapter(new AsyncStorageAdapter());
    return;
  }

  try {
    const mmkvModule = (await import('react-native-mmkv')) as any;
    const MMKVClass = mmkvModule.MMKV;
    const mmkv = new MMKVClass({ id: 'gurudevi-store' });
    storage.registerAdapter(new MMKVStorageAdapter(mmkv));
  } catch (e) {
    console.warn('Boot: MMKV init failed, falling back to AsyncStorage', e);
    storage.registerAdapter(new AsyncStorageAdapter());
  }
}

import { supabase } from '../../api/supabase';
// Note: We'll use dynamic imports or passing refs for communityAPI to avoid circular deps if necessary,
// but for now let's assume core is the base.
import type { AuthorityTier, QRPayload } from '../../types';

export type FlowOutcome = 'success' | 'error' | 'pending_auth' | 'redirect';

export type FlowIntent = 'GOTO_CLASSROOM' | 'GOTO_COMMUNITY' | 'GOTO_SELF' | 'GOTO_THUTHIMAL_CLAIM';

export interface FlowResult {
  outcome: FlowOutcome;
  message: string;
  intent?: FlowIntent;
  params?: any;
  error?: any;
}

/**
 * FlowResolver
 *
 * Central orchestrator for "Intent-to-Action" journeys.
 * Handles parsing, validation, and execution for:
 * - QR Scans
 * - Deep Links
 * - Manual Invite Codes
 */
export class FlowResolver {
  /**
   * Resolve a QR payload into a system action.
   */
  static async resolveQR(payload: QRPayload, userId: string): Promise<FlowResult> {
    try {
      switch (payload.action) {
        case 'join_school':
          return await FlowResolver.executeJoinSchool(
            payload.school_id,
            payload.group_id,
            userId,
            payload.handle,
          );

        case 'join_class':
          return await FlowResolver.executeJoinClass(payload.classroom_id, userId, payload.handle);

        case 'join_group':
          return await FlowResolver.executeJoinGroup(payload.group_id, userId, payload.handle);

        case 'claim_invite':
          return await FlowResolver.executeClaimInvite(
            payload.invite_code,
            payload.school_id,
            payload.authority as AuthorityTier,
            userId,
          );

        case 'user_invite':
          return {
            outcome: 'success',
            message: 'Welcome! Referral attribution stored.',
            intent: 'GOTO_SELF',
          };

        case 'thuthimal_gift':
          return {
            outcome: 'redirect',
            message: 'Redirecting to Thuthimal claim...',
            intent: 'GOTO_THUTHIMAL_CLAIM',
            params: {
              gift_token: payload.gift_token,
              gifter_name: payload.gifter_name,
            },
          };

        default:
          return { outcome: 'error', message: 'Unknown action' };
      }
    } catch (error: any) {
      console.error('[FlowResolver] Execution error:', error);
      return {
        outcome: 'error',
        message: error.message || 'Action failed',
        error,
      };
    }
  }

  private static async executeJoinSchool(
    schoolId: string,
    groupId: string,
    userId: string,
    handle?: string,
  ): Promise<FlowResult> {
    let finalSchoolId = schoolId;
    let finalGroupId = groupId;

    // Resolve handle if present
    if (handle?.startsWith('@')) {
      const h = handle.slice(1);
      const { data: school } = await supabase
        .from('schools')
        .select('id, community_group_id')
        .eq('handle', h)
        .single();
      if (school) {
        finalSchoolId = school.id;
        finalGroupId = school.community_group_id || groupId;
      }
    }

    // 1. Update user's school association
    const { error: userError } = await supabase
      .from('users')
      .update({ school_id: finalSchoolId })
      .eq('id', userId);

    if (userError) throw userError;

    // 2. Join the automated school community group
    const { error: groupError } = await supabase.from('group_members').upsert({
      group_id: finalGroupId,
      user_id: userId,
      status: 'active',
      is_admin: false,
    });

    if (groupError) console.warn('[FlowResolver] Group join warning:', groupError);

    return {
      outcome: 'success',
      message: 'Successfully joined school and community!',
      intent: 'GOTO_CLASSROOM',
    };
  }

  private static async executeJoinClass(
    classroomId: string,
    userId: string,
    handle?: string,
  ): Promise<FlowResult> {
    let finalClassroomId = classroomId;
    if (handle?.startsWith('@')) {
      const h = handle.slice(1);
      const { data: cls } = await supabase.from('classrooms').select('id').eq('handle', h).single();
      if (cls) finalClassroomId = cls.id;
    }

    // Look up the user's role so we can route correctly
    const { data: userData } = await supabase
      .from('users')
      .select('role')
      .eq('id', userId)
      .single();

    const role = userData?.role ?? 'student';

    if (role === 'student') {
      // Students join via the classroom_students membership table
      const { error } = await supabase
        .from('classroom_students')
        .upsert(
          { classroom_id: finalClassroomId, student_id: userId },
          { onConflict: 'classroom_id,student_id' },
        );
      if (error) throw error;
    } else {
      // Teachers/staff: only claim teacher_id if the classroom has no teacher yet.
      const { data: classroom, error: fetchError } = await supabase
        .from('classrooms')
        .select('teacher_id')
        .eq('id', finalClassroomId)
        .single();

      if (fetchError) throw fetchError;

      if (!classroom?.teacher_id) {
        // Unclaimed classroom  claim atomically, only if still null
        const { data: claimed, error: updateError } = await supabase
          .from('classrooms')
          .update({ teacher_id: userId })
          .eq('id', finalClassroomId)
          .is('teacher_id', null)
          .select('id');
        if (updateError) throw updateError;
        // If 0 rows were updated another teacher claimed it first  navigate as a visitor
        if (!claimed || claimed.length === 0) {
          return {
            outcome: 'success',
            message: 'Joined classroom. Ownership was already claimed by another teacher.',
            intent: 'GOTO_CLASSROOM',
          };
        }
      }
      // If classroom already has a teacher, just navigate  no ownership change.
    }

    return {
      outcome: 'success',
      message: 'Joined classroom successfully!',
      intent: 'GOTO_CLASSROOM',
    };
  }

  private static async executeJoinGroup(
    groupId: string,
    userId: string,
    handle?: string,
  ): Promise<FlowResult> {
    let finalGroupId = groupId;
    if (handle?.startsWith('@')) {
      const h = handle.slice(1);
      const { data: group } = await supabase
        .from('community_groups')
        .select('id')
        .eq('handle', h)
        .single();
      if (group) finalGroupId = group.id;
    }

    const { error } = await supabase.from('group_members').upsert({
      group_id: finalGroupId,
      user_id: userId,
      status: 'active',
    });

    if (error) throw error;

    return {
      outcome: 'success',
      message: 'Joined community group!',
      intent: 'GOTO_COMMUNITY',
    };
  }

  private static async executeClaimInvite(
    inviteCode: string,
    _schoolId: string,
    role: AuthorityTier,
    userId: string,
  ): Promise<FlowResult> {
    try {
      if (__DEV__) {
        console.log(`[FlowResolver] Executing transactional invite claim for code: ${inviteCode}`);
      }

      // Atomic RPC call
      const { data, error } = await supabase.rpc('claim_invite_code', {
        p_invite_code: inviteCode,
        p_user_id: userId,
      });

      if (error) throw error;
      if (data && !data.success) {
        return {
          outcome: 'error',
          message: data.message || 'Failed to claim invite',
        };
      }

      return {
        outcome: 'success',
        message: `Welcome to the school as a ${role}!`,
        intent: 'GOTO_CLASSROOM',
      };
    } catch (error: any) {
      console.error('[FlowResolver] Claim error:', error);
      return {
        outcome: 'error',
        message: error.message || 'Claim failed',
        error,
      };
    }
  }
}

import { SafeZustandStorage } from './storageWrapper';

// Keys for MMKV storage
const GUEST_TIMETABLE_KEY = 'guest-timetable';
const GUEST_MOOD_LOGS_KEY = 'guest-mood-logs';
const GUEST_JOURNAL_ENTRIES_KEY = 'guest-journal-entries';
const GUEST_CLASSROOM_DATA_KEY = 'guest-classroom-data';
const GUEST_STUDENTS_KEY = 'guest-students';

export interface GuestTimetablePeriod {
  localId: string;
  day_of_week: number;
  period_number: number;
  subject: string;
  class_name: string;
  type: 'subject' | 'relief' | 'interval';
  start_time: string;
  end_time: string;
}

export interface GuestMoodLog {
  localId: string;
  mood: number;
  note?: string;
  timestamp: string;
}

export interface GuestJournalEntry {
  localId: string;
  content: string;
  timestamp: string;
}

export interface GuestStudent {
  localId: string;
  name: string;
  index_number: string;
  notes?: string;
}

/**
 * Guest Data Manager
 * Handles local storage for anonymous users using MMKV
 * Data is stored locally and synced to Supabase upon account creation
 */
export class GuestDataManager {
  // ============ Timetable Methods ============

  static async getTimetable(dayOfWeek: number): Promise<GuestTimetablePeriod[]> {
    try {
      const data = await SafeZustandStorage.getItem(GUEST_TIMETABLE_KEY);
      if (!data) return [];

      const allPeriods: GuestTimetablePeriod[] = JSON.parse(data);
      return allPeriods.filter((p) => p.day_of_week === dayOfWeek);
    } catch (error) {
      console.error('Failed to get guest timetable:', error);
      return [];
    }
  }

  static async addTimetablePeriod(
    period: Omit<GuestTimetablePeriod, 'localId'>,
  ): Promise<GuestTimetablePeriod> {
    try {
      const data = await SafeZustandStorage.getItem(GUEST_TIMETABLE_KEY);
      const allPeriods: GuestTimetablePeriod[] = data ? JSON.parse(data) : [];

      const newPeriod: GuestTimetablePeriod = {
        ...period,
        localId: `local-${Date.now()}-${Math.random()}`,
      };

      allPeriods.push(newPeriod);
      await SafeZustandStorage.setItem(GUEST_TIMETABLE_KEY, JSON.stringify(allPeriods));

      return newPeriod;
    } catch (error) {
      console.error('Failed to add guest timetable period:', error);
      throw error;
    }
  }

  static async updateTimetablePeriod(
    localId: string,
    updates: Partial<GuestTimetablePeriod>,
  ): Promise<void> {
    try {
      const data = await SafeZustandStorage.getItem(GUEST_TIMETABLE_KEY);
      if (!data) return;

      const allPeriods: GuestTimetablePeriod[] = JSON.parse(data);
      const index = allPeriods.findIndex((p) => p.localId === localId);

      if (index !== -1) {
        allPeriods[index] = {
          ...allPeriods[index],
          ...updates,
        } as GuestTimetablePeriod;
        await SafeZustandStorage.setItem(GUEST_TIMETABLE_KEY, JSON.stringify(allPeriods));
      }
    } catch (error) {
      console.error('Failed to update guest timetable period:', error);
      throw error;
    }
  }

  static async deleteTimetablePeriod(localId: string): Promise<void> {
    try {
      const data = await SafeZustandStorage.getItem(GUEST_TIMETABLE_KEY);
      if (!data) return;

      const allPeriods: GuestTimetablePeriod[] = JSON.parse(data);
      const filtered = allPeriods.filter((p) => p.localId !== localId);

      await SafeZustandStorage.setItem(GUEST_TIMETABLE_KEY, JSON.stringify(filtered));
    } catch (error) {
      console.error('Failed to delete guest timetable period:', error);
      throw error;
    }
  }

  // ============ Mood Log Methods ============

  static async getMoodLogs(): Promise<GuestMoodLog[]> {
    try {
      const data = await SafeZustandStorage.getItem(GUEST_MOOD_LOGS_KEY);
      return data ? JSON.parse(data) : [];
    } catch (error) {
      console.error('Failed to get guest mood logs:', error);
      return [];
    }
  }

  static async addMoodLog(mood: number, note?: string): Promise<GuestMoodLog> {
    try {
      const data = await SafeZustandStorage.getItem(GUEST_MOOD_LOGS_KEY);
      const logs: GuestMoodLog[] = data ? JSON.parse(data) : [];

      const newLog: GuestMoodLog = {
        localId: `local-${Date.now()}-${Math.random()}`,
        mood,
        note,
        timestamp: new Date().toISOString(),
      };

      logs.push(newLog);
      await SafeZustandStorage.setItem(GUEST_MOOD_LOGS_KEY, JSON.stringify(logs));

      return newLog;
    } catch (error) {
      console.error('Failed to add guest mood log:', error);
      throw error;
    }
  }

  // ============ Journal Entry Methods ============

  static async getJournalEntries(): Promise<GuestJournalEntry[]> {
    try {
      const data = await SafeZustandStorage.getItem(GUEST_JOURNAL_ENTRIES_KEY);
      return data ? JSON.parse(data) : [];
    } catch (error) {
      console.error('Failed to get guest journal entries:', error);
      return [];
    }
  }

  static async addJournalEntry(content: string): Promise<GuestJournalEntry> {
    try {
      const data = await SafeZustandStorage.getItem(GUEST_JOURNAL_ENTRIES_KEY);
      const entries: GuestJournalEntry[] = data ? JSON.parse(data) : [];

      const newEntry: GuestJournalEntry = {
        localId: `local-${Date.now()}-${Math.random()}`,
        content,
        timestamp: new Date().toISOString(),
      };

      entries.push(newEntry);
      await SafeZustandStorage.setItem(GUEST_JOURNAL_ENTRIES_KEY, JSON.stringify(entries));

      return newEntry;
    } catch (error) {
      console.error('Failed to add guest journal entry:', error);
      throw error;
    }
  }

  // ============ Student Methods ============

  static async getStudents(): Promise<GuestStudent[]> {
    try {
      const data = await SafeZustandStorage.getItem(GUEST_STUDENTS_KEY);
      return data ? JSON.parse(data) : [];
    } catch (error) {
      console.error('Failed to get guest students:', error);
      return [];
    }
  }

  static async addStudents(students: Omit<GuestStudent, 'localId'>[]): Promise<GuestStudent[]> {
    try {
      const data = await SafeZustandStorage.getItem(GUEST_STUDENTS_KEY);
      const existing: GuestStudent[] = data ? JSON.parse(data) : [];

      const newStudents = students.map((s) => ({
        ...s,
        localId: `local-${Date.now()}-${Math.random()}`,
      }));

      const updated = [...existing, ...newStudents];
      await SafeZustandStorage.setItem(GUEST_STUDENTS_KEY, JSON.stringify(updated));

      return newStudents;
    } catch (error) {
      console.error('Failed to add guest students:', error);
      throw error;
    }
  }

  // ============ Data Summary & Clearing ============

  static async getDataSummary(): Promise<{
    timetablePeriods: number;
    moodLogs: number;
    journalEntries: number;
    students: number;
  }> {
    const [timetableData, moodData, journalData, studentData] = await Promise.all([
      SafeZustandStorage.getItem(GUEST_TIMETABLE_KEY),
      SafeZustandStorage.getItem(GUEST_MOOD_LOGS_KEY),
      SafeZustandStorage.getItem(GUEST_JOURNAL_ENTRIES_KEY),
      SafeZustandStorage.getItem(GUEST_STUDENTS_KEY),
    ]);

    return {
      timetablePeriods: timetableData ? JSON.parse(timetableData).length : 0,
      moodLogs: moodData ? JSON.parse(moodData).length : 0,
      journalEntries: journalData ? JSON.parse(journalData).length : 0,
      students: studentData ? JSON.parse(studentData).length : 0,
    };
  }

  static async clearAllGuestData(): Promise<void> {
    await Promise.all([
      SafeZustandStorage.removeItem(GUEST_TIMETABLE_KEY),
      SafeZustandStorage.removeItem(GUEST_MOOD_LOGS_KEY),
      SafeZustandStorage.removeItem(GUEST_JOURNAL_ENTRIES_KEY),
      SafeZustandStorage.removeItem(GUEST_STUDENTS_KEY),
      SafeZustandStorage.removeItem(GUEST_CLASSROOM_DATA_KEY),
    ]);
  }

  // ============ Data Export (for sync) ============

  static async exportAllData(): Promise<{
    timetable: GuestTimetablePeriod[];
    moodLogs: GuestMoodLog[];
    journalEntries: GuestJournalEntry[];
    students: GuestStudent[];
  }> {
    const [timetableData, moodData, journalData, studentData] = await Promise.all([
      SafeZustandStorage.getItem(GUEST_TIMETABLE_KEY),
      SafeZustandStorage.getItem(GUEST_MOOD_LOGS_KEY),
      SafeZustandStorage.getItem(GUEST_JOURNAL_ENTRIES_KEY),
      SafeZustandStorage.getItem(GUEST_STUDENTS_KEY),
    ]);

    return {
      timetable: timetableData ? JSON.parse(timetableData) : [],
      moodLogs: moodData ? JSON.parse(moodData) : [],
      journalEntries: journalData ? JSON.parse(journalData) : [],
      students: studentData ? JSON.parse(studentData) : [],
    };
  }
}

import { authAPI } from '../api/auth';
import { supabase } from '../api/supabase';
import { GuestDataManager } from './guestDataManager';

export interface SyncProgress {
  total: number;
  completed: number;
  currentStep: string;
  errors: string[];
}

export type SyncProgressCallback = (progress: SyncProgress) => void;

/**
 * Guest Data Sync Service
 *
 * Handles migration of locally stored guest data to Supabase when a user creates an account.
 * This service ensures seamless data continuity during the guest \u2192 authenticated user transition.
 */
export class GuestDataSync {
  /**
   * Syncs all guest data to Supabase for the authenticated user
   * @param userId The authenticated user's ID from Supabase
   * @param onProgress Optional callback for progress updates
   * @returns Summary of sync results
   */
  static async syncAllData(
    userId: string,
    onProgress?: SyncProgressCallback,
  ): Promise<{
    success: boolean;
    synced: {
      timetable: number;
      moodLogs: number;
      journalEntries: number;
      students: number;
    };
    errors: string[];
  }> {
    const errors: string[] = [];
    const synced = {
      timetable: 0,
      moodLogs: 0,
      journalEntries: 0,
      students: 0,
    };

    try {
      // Check if user is still anonymous
      const isAnon = await authAPI.isAnonymous();
      if (isAnon) {
        throw new Error('Cannot sync data for anonymous user');
      }

      // Export all guest data
      const guestData = await GuestDataManager.exportAllData();
      const totalItems =
        guestData.timetable.length +
        guestData.moodLogs.length +
        guestData.journalEntries.length +
        guestData.students.length;

      let completed = 0;

      // Helper to update progress
      const updateProgress = (step: string) => {
        if (onProgress) {
          onProgress({
            total: totalItems,
            completed,
            currentStep: step,
            errors: [...errors],
          });
        }
      };

      // 1. Sync Timetable \u2014 batch insert for all periods
      updateProgress('Syncing timetable periods...');
      if (guestData.timetable.length > 0) {
        const timetableRows = guestData.timetable.map((period) => ({
          user_id: userId,
          day_of_week: period.day_of_week,
          period_number: period.period_number,
          subject: period.subject,
          class_name: period.class_name,
          type: period.type,
          start_time: period.start_time,
          end_time: period.end_time,
        }));
        const { error } = await supabase.from('timetable').insert(timetableRows);
        if (!error) {
          synced.timetable = timetableRows.length;
        } else {
          errors.push(`Timetable: ${error.message}`);
        }
        completed += guestData.timetable.length;
        updateProgress('Syncing timetable periods...');
      }

      // 2. Sync Mood Logs \u2014 batch insert
      updateProgress('Syncing mood logs...');
      const moodMap = ['joyful', 'calm', 'curious', 'anxious', 'frustrated', 'sad'];
      if (guestData.moodLogs.length > 0) {
        const moodRows = guestData.moodLogs.map((log) => ({
          user_id: userId,
          mood: moodMap[log.mood],
          note: log.note,
          created_at: log.timestamp,
        }));
        const { error } = await supabase.from('mood_logs').insert(moodRows);
        if (!error) {
          synced.moodLogs = moodRows.length;
        } else {
          errors.push(`Mood logs: ${error.message}`);
        }
        completed += guestData.moodLogs.length;
        updateProgress('Syncing mood logs...');
      }

      // 3. Sync Journal Entries \u2014 batch insert
      updateProgress('Syncing journal entries...');
      if (guestData.journalEntries.length > 0) {
        const journalRows = guestData.journalEntries.map((entry) => ({
          user_id: userId,
          content: entry.content,
          created_at: entry.timestamp,
        }));
        const { error } = await supabase.from('journal_entries').insert(journalRows);
        if (!error) {
          synced.journalEntries = journalRows.length;
        } else {
          errors.push(`Journal entries: ${error.message}`);
        }
        completed += guestData.journalEntries.length;
        updateProgress('Syncing journal entries...');
      }

      // 4. Sync Students \u2014 batch insert (teachers only)
      updateProgress('Syncing students...');
      if (guestData.students.length > 0) {
        const studentRows = guestData.students.map((student) => ({
          full_name: student.name,
          index_number: student.index_number,
          notes: student.notes,
          // Note: class_id would need to be set separately if creating a classroom
        }));
        const { error } = await supabase.from('students').insert(studentRows);
        if (!error) {
          synced.students = studentRows.length;
        } else {
          errors.push(`Students: ${error.message}`);
        }
        completed += guestData.students.length;
        updateProgress('Syncing students...');
      }

      // Final progress update
      updateProgress('Sync complete!');

      // Clear guest data after successful sync
      if (errors.length === 0) {
        await GuestDataManager.clearAllGuestData();
      }

      return {
        success: errors.length === 0,
        synced,
        errors,
      };
    } catch (error: any) {
      errors.push(`Fatal sync error: ${error.message}`);
      return {
        success: false,
        synced,
        errors,
      };
    }
  }

  /**
   * Checks if there's guest data available to sync
   */
  static async hasGuestData(): Promise<boolean> {
    const summary = await GuestDataManager.getDataSummary();
    return (
      summary.timetablePeriods > 0 ||
      summary.moodLogs > 0 ||
      summary.journalEntries > 0 ||
      summary.students > 0
    );
  }

  /**
   * Gets a summary of guest data available for sync
   */
  static async getGuestDataSummary(): Promise<{
    timetablePeriods: number;
    moodLogs: number;
    journalEntries: number;
    students: number;
    total: number;
  }> {
    const summary = await GuestDataManager.getDataSummary();
    return {
      ...summary,
      total:
        summary.timetablePeriods + summary.moodLogs + summary.journalEntries + summary.students,
    };
  }
}

import NetInfo from '@react-native-community/netinfo';
import * as Device from 'expo-device';
import * as Haptics from 'expo-haptics';
import * as Location from 'expo-location';
import { Linking, Platform, Share, StatusBar } from 'react-native';
import type {
  CoreRuntimeEnvironment,
  DeviceMetadata,
  HapticsProvider,
  LinkingProvider,
  LocationProvider,
  NetworkProvider,
  ShareOptions,
  ShareProvider,
  UIProvider,
} from '../types/runtime';
import { storage } from './storage';

export const nativeStorageProvider = {
  async getItem(key: string) {
    return storage.getStringAsync(key);
  },
  async setItem(key: string, value: string) {
    storage.set(key, value);
  },
  async removeItem(key: string) {
    storage.delete(key);
  },
};

export const nativeDeviceProvider = {
  getMetadata(): DeviceMetadata {
    const constants = (Platform.constants ?? {}) as Record<string, unknown>;
    const brand = typeof constants['Brand'] === 'string' ? constants['Brand'].trim() : '';
    const model = typeof constants['Model'] === 'string' ? constants['Model'].trim() : '';
    const parts = [brand, model].filter(Boolean);

    return {
      modelName: parts.length > 0 ? parts.join(' ') : Platform.OS,
      osVersion: Platform.Version == null ? null : String(Platform.Version),
      platform: Platform.OS,
    };
  },
  getTotalMemory: () => Device.totalMemory,
};

export const nativeHapticsProvider: HapticsProvider = {
  impactLight: () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light),
  impactMedium: () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium),
  impactHeavy: () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy),
  notificationSuccess: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success),
  notificationWarning: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning),
  notificationError: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error),
  selection: () => Haptics.selectionAsync(),
};

export const nativeLinkingProvider: LinkingProvider = {
  openURL: (url: string) => Linking.openURL(url),
  canOpenURL: (url: string) => Linking.canOpenURL(url),
};

export const nativeLocationProvider: LocationProvider = {
  requestPermissionsAsync: () => Location.requestForegroundPermissionsAsync(),
  watchPositionAsync: (options: any, callback: (location: any) => void) =>
    Location.watchPositionAsync(options, callback),
