import * as NativeSentry from '@sentry/react-native';
import { Platform } from 'react-native';

type BrowserSentryModule = typeof import('@sentry/browser');

let browserSentryPromise: Promise<BrowserSentryModule | null> | null = null;
let sentryInitialized = false;

function getSentryEnvironment() {
  return process.env['EXPO_PUBLIC_SENTRY_ENVIRONMENT'] || process.env['NODE_ENV'] || 'production';
}

function getSentryRelease() {
  return process.env['EXPO_PUBLIC_SENTRY_RELEASE'] || process.env['npm_package_version'] || undefined;
}

async function getBrowserSentry(): Promise<BrowserSentryModule | null> {
  if (Platform.OS !== 'web') return null;
  if (!browserSentryPromise) {
    browserSentryPromise = import('@sentry/browser').catch((error) => {
      console.error('[Sentry] Failed to load browser SDK:', error);
      return null;
    });
  }
  return browserSentryPromise;
}

/**
 * Initializes Sentry for the mobile application.
 */
export const initSentry = () => {
  if (sentryInitialized) return;
  if (__DEV__) {
    console.log('[Sentry Mock] Initialization skipped in development');
    return;
  }

  const dsn = process.env['EXPO_PUBLIC_SENTRY_DSN'];
  if (!dsn) {
    console.warn('[Sentry] DSN missing');
    return;
  }

  if (Platform.OS === 'web') {
    void getBrowserSentry().then((BrowserSentry) => {
      if (!BrowserSentry || sentryInitialized) return;
      BrowserSentry.init({
        dsn,
        environment: getSentryEnvironment(),
        release: getSentryRelease(),
        debug: false,
        sendDefaultPii: false,
        initialScope: {
          tags: {
            app_platform: 'web',
            app_name: 'gurudevi-mobile',
          },
        },
      });
      sentryInitialized = true;
    });
    return;
  }

  NativeSentry.init({
    dsn,
    enableAutoSessionTracking: true,
    environment: getSentryEnvironment(),
    release: getSentryRelease(),
    debug: false,
  });
  sentryInitialized = true;
};

/**
 * Captures an exception and logs it to Sentry.
 */
export const captureException = (error: any, context?: any) => {
  console.error(error);
  if (__DEV__) {
    return;
  }

  if (Platform.OS === 'web') {
    void getBrowserSentry().then((BrowserSentry) => {
      BrowserSentry?.captureException(error, { extra: context });
    });
    return;
  }

  NativeSentry.captureException(error, { extra: context });
};

/**
 * Adds a breadcrumb to the current Sentry session.
 */
export const logBreadcrumb = (message: string, category?: string, data?: any) => {
  if (__DEV__) {
    console.log(`[Sentry Breadcrumb] ${category}: ${message}`, data);
    return;
  }

  if (Platform.OS === 'web') {
    void getBrowserSentry().then((BrowserSentry) => {
      BrowserSentry?.addBreadcrumb({
        message,
        category,
        data,
        level: 'info',
      });
    });
    return;
  }

  NativeSentry.addBreadcrumb({
    message,
    category,
    data,
  });
};

export const setSentryUser = (user: {
  id: string;
  email?: string | null;
  username?: string | null;
}) => {
  if (__DEV__) {
    return;
  }

  const sentryUser = {
    id: user.id,
    email: user.email ?? undefined,
    username: user.username ?? undefined,
  };

  if (Platform.OS === 'web') {
    void getBrowserSentry().then((BrowserSentry) => {
      BrowserSentry?.setUser(sentryUser);
    });
    return;
  }

  NativeSentry.setUser(sentryUser);
};

export const clearSentryUser = () => {
  if (__DEV__) {
    return;
  }

  if (Platform.OS === 'web') {
    void getBrowserSentry().then((BrowserSentry) => {
      BrowserSentry?.setUser(null);
    });
    return;
  }

  NativeSentry.setUser(null);
};

import AsyncStorage from '@react-native-async-storage/async-storage';

// Standard interface to ensure we can swap implementations
interface StorageInterface {
  set: (key: string, value: string | boolean | number) => void;
  getString: (key: string) => string | undefined;
  getStringAsync: (key: string) => Promise<string | undefined>;
  getBoolean: (key: string) => boolean | undefined;
  getNumber: (key: string) => number | undefined;
  delete: (key: string) => void;
  clearAll: () => void;
  contains: (key: string) => boolean;
}

/**
 * Robust AsyncStorage-based storage with in-memory cache for synchronous access.
 * This ensures getString/getBoolean work immediately while persisting in background.
 */
class RobustAsyncStorage implements StorageInterface {
  private cache = new Map<string, any>();
  private initialized = false;
  private initPromise: Promise<void> | null = null;

  constructor() {
    this.initPromise = this.init();
  }

  private async init() {
    try {
      const keys = await AsyncStorage.getAllKeys();
      const pairs = await AsyncStorage.multiGet(keys);
      pairs.forEach(([key, value]) => {
        if (value !== null) {
          // Try to parse number/boolean
          if (value === 'true') this.cache.set(key, true);
          else if (value === 'false') this.cache.set(key, false);
          else if (!Number.isNaN(Number(value)) && value.trim() !== '')
            this.cache.set(key, Number(value));
          else this.cache.set(key, value);
        }
      });
      this.initialized = true;
    } catch (_e) {
      // Silently fail during hydration to avoid HMR issues, or defer to a safe time
    }
  }

  set(key: string, value: string | boolean | number) {
    this.cache.set(key, value);
    AsyncStorage.setItem(key, String(value)).catch((e) =>
      console.error(`\uD83D\uDCE6 Storage: Failed to persist ${key}`, e),
    );
  }

  getString(key: string) {
    const val = this.cache.get(key);
    return typeof val === 'string' ? val : undefined;
  }

  async getStringAsync(key: string) {
    if (!this.initialized && this.initPromise) await this.initPromise;
    const val = await AsyncStorage.getItem(key);
    return val || undefined;
  }

  getBoolean(key: string) {
    const val = this.cache.get(key);
    return typeof val === 'boolean' ? val : undefined;
  }

  getNumber(key: string) {
    const val = this.cache.get(key);
    return typeof val === 'number' ? val : undefined;
  }

  delete(key: string) {
    this.cache.delete(key);
    AsyncStorage.removeItem(key);
  }

  clearAll() {
    this.cache.clear();
    AsyncStorage.clear();
  }

  contains(key: string) {
    return this.cache.has(key);
  }
}

import Constants, { ExecutionEnvironment } from 'expo-constants';
import { Platform } from 'react-native';

/**
 * Storage singleton \u2014 lazily initialized on first access.
 *
 * WHY LAZY?
 * react-native-mmkv v4 uses NitroModules (JSI). The native C++ module is
 * registered before JS executes, but importing storage.ts at module-load time
 * (before React mounts) risks hitting initialization-order issues on some
 * devices. Lazy init means MMKV is only created when the first read/write
 * actually happens, safely inside the React lifecycle.
 *
 * ENGINE SELECTION:
 *   Expo Go (storeClient)  \u2192 RobustAsyncStorage (MMKV can't link in Expo Go)
 *   Dev build / standalone \u2192 MMKV native via NitroModules (fast, synchronous)
 *                            Falls back to RobustAsyncStorage if MMKV fails.
 *
 * MMKV BUILD REQUIREMENTS (dev build must have these):
 *   1. react-native-mmkv and react-native-nitro-modules in package.json  \u2713
 *   2. React Native New Architecture (mandatory in Expo 55+)                  \u2713
 *   3. expo prebuild + expo run:android (NOT just expo start)
 *      The native module must be compiled into the dev client APK.
 *      Running `expo start --dev-client` against an OLD APK that predates
 *      MMKV being added will silently fall back to AsyncStorage.
 */
import { Runtime } from './runtime';

let _storageInstance: StorageInterface | null = null;

function createStorage(): StorageInterface {
  const isExpoGo = Constants.executionEnvironment === ExecutionEnvironment.StoreClient;
  // MMKV is a JSI native module - unavailable in Expo Go (JS-only runtime) and on web.
  // ALSO: Defer MMKV init until the runtime is marked ready to avoid Bridgeless context race.
  const shouldUseAsyncStorage = isExpoGo || Platform.OS === 'web' || !Runtime.isReady();

  if (shouldUseAsyncStorage) {
    if (__DEV__) {
      const reason = isExpoGo
        ? 'Expo Go'
        : Platform.OS === 'web'
          ? 'Web'
          : 'Early Init (Deferring to AsyncStorage)';
      console.log(`\uD83D\uDCE6 Storage: ${reason} - using AsyncStorage fallback`);
    }
    return new RobustAsyncStorage();
  }

  try {
    const { MMKV } = require('react-native-mmkv');
    const mmkv = new MMKV({ id: 'gurudevi-store' });

    // Probe: verify the native instance actually works before committing.
    const PROBE_KEY = '__mmkv_probe__';
    mmkv.set(PROBE_KEY, '1');
    const probeResult = mmkv.getString(PROBE_KEY);
    mmkv.delete(PROBE_KEY);

    if (probeResult !== '1') throw new Error('MMKV probe read/write mismatch');

    if (__DEV__) console.log('\uD83D\uDCE6 Storage: MMKV v4 (NitroModules) initialized \u2713');

    // Wrap native MMKV instance to satisfy StorageInterface fully.
    return {
      set: (key, value) => mmkv.set(key, value),
      getString: (key) => mmkv.getString(key),
      getStringAsync: async (key) => mmkv.getString(key),
      getNumber: (key) => mmkv.getNumber(key),
      getBoolean: (key) => mmkv.getBoolean(key),
      delete: (key) => mmkv.delete(key),
      clearAll: () => mmkv.clearAll(),
      contains: (key) => mmkv.contains(key),
    };
  } catch (e) {
    if (__DEV__) {
      console.warn(
        '\uD83D\uDCE6 Storage: MMKV init failed \u2014 falling back to AsyncStorage.\n' +
          '  If this is unexpected, check:\n' +
          '    1. expo prebuild && expo run:android was run after adding MMKV\n' +
          '    2. New Architecture is enabled (Mandatory in Expo 55)\n' +
          '    3. react-native-nitro-modules version compatibility\n' +
          '  Error:',
        e,
      );
    }
    return new RobustAsyncStorage();
  }
}

function getStorage(): StorageInterface {
  const isExpoGo = Constants.executionEnvironment === ExecutionEnvironment.StoreClient;
  const isPermanentFallback = isExpoGo || Platform.OS === 'web';

  // If we have a cached instance, use it.
  if (_storageInstance) return _storageInstance;

  // If we are NOT ready and it's not a permanent fallback, return a TEMPORARY
  // RobustAsyncStorage but do NOT cache it. This forces the Proxy to keep
  // checking until Runtime.isReady() enters the MMKV branch.
  if (!Runtime.isReady() && !isPermanentFallback) {
    if (__DEV__)
      console.log('\uD83D\uDCE6 Storage: Early access - providing temporary AsyncStorage');
    return new RobustAsyncStorage();
  }

  const instance = createStorage();

  // Cache the instance permanently now that we are ready or it's a permanent fallback.
  _storageInstance = instance;
  return instance;
}

/**
 * storage \u2014 the app's unified KV store.
 *
 * Uses a Proxy so that all method calls go through lazy initialization,
 * meaning MMKV is never instantiated until the first actual read/write.
 * This avoids NitroModules JSI timing issues during app startup.
 */
export const storage: StorageInterface = new Proxy({} as StorageInterface, {
  get(_target, prop: string | symbol) {
    const instance = getStorage() as any;
    if (typeof prop === 'symbol') {
      return Reflect.get(instance, prop);
    }
    const value = instance[prop as keyof typeof instance];
    if (typeof value === 'function') {
      return value.bind(instance);
    }
    return value;
  },
});

export const StorageKeys = {
  USER_PREFERENCES: 'user_preferences',
  LAST_SYNC: 'last_sync',
  CACHED_COMMUNITY_POSTS: 'cached_community_posts',
  CACHED_GROUPS: 'cached_groups',
};

/** @internal \u2014 exposed only for testing. Resets the singleton so tests can inject a fresh instance. */
export function _resetStorageForTesting() {
  _storageInstance = null;
}

import AsyncStorage from '@react-native-async-storage/async-storage';
import type { StateStorage } from 'zustand/middleware';
import { storage } from './storage';

/**
 * A failsafe storage wrapper for Zustand.
 * It prioritizes our custom storage instance (MMKV with fallbacks)
 * but provides an explicit interface for Zustand's persist middleware.
 */
export const SafeZustandStorage: StateStorage = {
  getItem: (name: string): string | null | Promise<string | null> => {
    // MMKV is synchronous
    const value = storage.getString(name);
    if (value !== undefined) return value;

    // Fallback to AsyncStorage if we are in an environment where MMKV didn't init
    return AsyncStorage.getItem(name);
  },
  setItem: (name: string, value: string): void | Promise<void> => {
    try {
      storage.set(name, value);
    } catch (_e) {
      // Fallback for set
      return AsyncStorage.setItem(name, value);
    }
  },
  removeItem: (name: string): void | Promise<void> => {
    try {
      storage.delete(name);
    } catch (_e) {
      return AsyncStorage.removeItem(name);
    }
  },
};

import AsyncStorage from '@react-native-async-storage/async-storage';
import * as SecureStore from 'expo-secure-store';
import { Platform } from 'react-native';
import { getActiveAccountId, scopeStorageKey } from '../lib/accountScope';

const supabaseUrl = process.env['EXPO_PUBLIC_SUPABASE_URL'];

function getProjectRef() {
  if (!supabaseUrl) return 'default';

  try {
    const hostname = new URL(supabaseUrl).hostname;
    return hostname.split('.')[0]! || 'default';
  } catch {
    return 'default';
  }
}

const AUTH_TOKEN_STORAGE_KEY = `sb-${getProjectRef()}-auth-token`;

async function readStorage(key: string): Promise<string | null> {
  if (Platform.OS === 'web') {
    return AsyncStorage.getItem(key);
  }

  return SecureStore.getItemAsync(key);
}

async function writeStorage(key: string, value: string): Promise<void> {
  if (Platform.OS === 'web') {
    await AsyncStorage.setItem(key, value);
    return;
  }

  await SecureStore.setItemAsync(key, value);
}

async function deleteStorage(key: string): Promise<void> {
  if (Platform.OS === 'web') {
    await AsyncStorage.removeItem(key);
    return;
  }

  await SecureStore.deleteItemAsync(key);
}

function getScopedAuthStorageKey(accountId: string | null, key: string) {
  return scopeStorageKey(`auth:${key}`, accountId);
}

function normalizeStoredSession(parsed: unknown) {
  if (!parsed || typeof parsed !== 'object') return null;

  const direct = parsed as { access_token?: string; refresh_token?: string };
  if (direct.access_token && direct.refresh_token) {
    return direct;
  }

  const nested = parsed as {
    currentSession?: { access_token?: string; refresh_token?: string };
  };
  if (nested.currentSession?.access_token && nested.currentSession?.refresh_token) {
    return nested.currentSession;
  }

  return null;
}

export const supabaseAuthStorage = {
  async getItem(key: string) {
    const scopedKey = getScopedAuthStorageKey(getActiveAccountId(), key);
    const scopedValue = await readStorage(scopedKey);
    if (scopedValue != null) {
      return scopedValue;
    }

    return readStorage(key);
  },

  async setItem(key: string, value: string) {
    const scopedKey = getScopedAuthStorageKey(getActiveAccountId(), key);
    await writeStorage(scopedKey, value);
  },

  async removeItem(key: string) {
    const scopedKey = getScopedAuthStorageKey(getActiveAccountId(), key);
    await deleteStorage(scopedKey);
    await deleteStorage(key);
  },
};

export async function getStoredSessionForAccount(accountId: string | null) {
  const raw = await readStorage(getScopedAuthStorageKey(accountId, AUTH_TOKEN_STORAGE_KEY));
  if (!raw) return null;

  try {
    return normalizeStoredSession(JSON.parse(raw));
  } catch {
    return null;
  }
}

export async function setStoredSessionForAccount(
  accountId: string | null,
  session: { access_token: string; refresh_token: string },
) {
  await writeStorage(
    getScopedAuthStorageKey(accountId, AUTH_TOKEN_STORAGE_KEY),
    JSON.stringify(session),
  );
}

export async function removeStoredSessionForAccount(accountId: string | null) {
  await deleteStorage(getScopedAuthStorageKey(accountId, AUTH_TOKEN_STORAGE_KEY));
}

export async function clearLegacySupabaseSession() {
  await deleteStorage(AUTH_TOKEN_STORAGE_KEY);
}

import { storage } from '../lib/storage';
import { handleAPIError } from '../logic/apiInterceptor';

/**
 * Resilience Configuration
 */
export interface ResilienceOptions {
  key: string; // Storage key for caching
  ttl?: number; // Time to live in milliseconds (default: 1 hour)
  silent?: boolean; // If true, don't show toast on fetch error
}

/**
 * Offline-First Fetcher (Resilience Layer)
 * 1. Returns cached data immediately if available.
 * 2. Fetches fresh data in the background.
 * 3. Updates cache and notifies listeners if data changed.
 */
export async function withResilience<T>(
  fetcher: () => Promise<T>,
  options: ResilienceOptions,
): Promise<T | null> {
  const { key, ttl = 3600000, silent = false } = options;

  // 1. Try to get from Cache
  const cachedRaw = storage.getString(key);
  let cachedData: T | null = null;
  let isExpired = true;

  if (cachedRaw) {
    try {
      const { data, timestamp } = JSON.parse(cachedRaw);
      cachedData = data;
      isExpired = Date.now() - timestamp > ttl;
    } catch (_e) {
      console.warn(`[Resilience] Failed to parse cache for ${key}`);
    }
  }

  // 2. Fetch fresh data if expired or missing
  const executeFetch = async () => {
    try {
      const freshData = await fetcher();
      if (freshData) {
        storage.set(
          key,
          JSON.stringify({
            data: freshData,
            timestamp: Date.now(),
          }),
        );
      }
      return freshData;
    } catch (error) {
      if (!silent) {
        handleAPIError(error);
      }
      return null;
    }
  };

  // If we have cached data and it's not expired, return it and fetch in background (Stale-While-Revalidate)
  if (cachedData && !isExpired) {
    executeFetch(); // Background refresh
    return cachedData;
  }

  // If expired or no cache, wait for fetch
  const freshData = await executeFetch();
  return freshData || cachedData; // Fallback to stale cache if fetch fails
}

/**
 * Clears resilience cache for a specific key
 */
export function invalidateResilience(key: string) {
  storage.delete(key);
}

import type React from 'react';
